const D=window.AUDIT_DATA;
const DB_NAME='audit_qmod_db_v2', STORE='audits', TEMPLATE_STORE='sop_templates', DB_VERSION=2, CURRENT_KEY='audit_qmod_current_id';
const NETWORK_SOP_ID='qos-network-audit';
const MASTER_TEMPLATE_FILE='Audit_QMOD_Master_Templates.xlsx';
const REPO_TEMPLATE_CACHE_KEY='audit_qmod_repo_template_pack_v1';
const modules={
  sop:{title:'SOP Audit',icon:'📋',desc:'SOP-specific compliance checklist'},
  wireless:{title:'Wireless BAS',icon:'📶',desc:'Wireless Broadband Access Service audit'},
  pcs:{title:'PCS',icon:'📱',desc:'Public Cellular Service measurement audit'},
  wired:{title:'Wired BAS',icon:'🔌',desc:'Wired Broadband Access Service audit'}
};
let db=null, records=[], sopTemplates=[], repoSopTemplates=[], liveModuleTemplates={}, repoTemplateMeta={source:'Built-in fallback',checkedAt:null,updated:false}, state=null, currentView='dashboard', currentModule=null, filter='all', sectionFilter='all', deferredInstall=null, sopManagerReturn='home';
const EMAIL_RECIPIENT='azlan.yusuff@mcmc.gov.my';
let compareSelection=new Set(), compareFilter='differences', reconcileFilter='review';
const now=()=>new Date().toISOString();
function uuid(){return crypto.randomUUID?crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0,v=c==='x'?r:(r&3|8);return v.toString(16)})}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function pct(n,d){return d?Math.round(n/d*100):0}
function clone(x){return JSON.parse(JSON.stringify(x))}
function ts(x){const n=Date.parse(x||0);return Number.isFinite(n)?n:0}
function fmtDate(x){try{return x?new Date(x).toLocaleString():'—'}catch(e){return '—'}}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains(STORE))d.createObjectStore(STORE,{keyPath:'id'});if(!d.objectStoreNames.contains(TEMPLATE_STORE))d.createObjectStore(TEMPLATE_STORE,{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function dbPut(x){return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(x);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function dbAll(){return new Promise((resolve,reject)=>{const r=db.transaction(STORE,'readonly').objectStore(STORE).getAll();r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error)})}
function dbTemplatePut(x){return new Promise((resolve,reject)=>{const tx=db.transaction(TEMPLATE_STORE,'readwrite');tx.objectStore(TEMPLATE_STORE).put(x);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function dbTemplateAll(){return new Promise((resolve,reject)=>{const r=db.transaction(TEMPLATE_STORE,'readonly').objectStore(TEMPLATE_STORE).getAll();r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error)})}
function dbTemplateDelete(id){return new Promise((resolve,reject)=>{const tx=db.transaction(TEMPLATE_STORE,'readwrite');tx.objectStore(TEMPLATE_STORE).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function hashString(v){let h=2166136261>>>0;for(const ch of String(v??'')){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)>>>0}return h.toString(16).padStart(8,'0')}
function slug(v){return String(v||'sop').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,48)||'sop'}
function normalizeTemplateItems(items,prefix='ITEM'){const seen=new Set();return (items||[]).filter(x=>x&&String(x.check||'').trim()&&String(x.check||'').trim().toLowerCase()!=='total').map((x,i)=>{let id=String(x.id||'').trim()||(`${prefix}-${String(i+1).padStart(3,'0')}`);if(seen.has(id))id=id+'-'+(i+1);seen.add(id);return {...x,id,section:String(x.section||'General').trim()||'General',check:String(x.check||'').trim(),evidenceExpected:String(x.evidenceExpected||'').trim(),sourceNo:x.sourceNo||i+1}})}
function normalizeSopTemplate(t){const base=clone(t||{});base.id=base.id||('sop-'+slug(base.name));base.name=String(base.name||'Unnamed SOP').trim();base.items=normalizeTemplateItems(base.items,'SOPC');base.fingerprint=base.fingerprint||hashString(base.id+'|'+base.name+'|'+(base.code||'')+'|'+(base.version||'')+'|'+base.items.map(x=>x.id+'|'+x.section+'|'+x.check+'|'+x.evidenceExpected).join('||'));return base}
function normalizeModuleTemplate(key,t){const base=clone(t||{}),fallbackName=modules[key]?.title||key;base.id=String(base.id||key).trim();base.name=String(base.name||fallbackName).trim();base.key=key;base.items=normalizeTemplateItems(base.items,key.toUpperCase());base.fingerprint=base.fingerprint||hashString(base.id+'|'+base.name+'|'+(base.version||'')+'|'+base.items.map(x=>x.id+'|'+x.section+'|'+x.check+'|'+x.evidenceExpected).join('||'));return base}
function fallbackModuleTemplates(){return {wireless:normalizeModuleTemplate('wireless',{id:'wireless-bas',name:'Wireless BAS',version:'legacy-v5.6',source:'Built-in fallback',items:clone(D.wirelessBas||[])}),pcs:normalizeModuleTemplate('pcs',{id:'pcs',name:'PCS',version:'legacy-v5.6',source:'Built-in fallback',items:clone(D.pcs||[])}),wired:normalizeModuleTemplate('wired',{id:'wired-bas',name:'Wired BAS',version:'legacy-v5.6',source:'Built-in fallback',items:clone(D.wiredBas||[])})}}
function fallbackNetworkSop(){return normalizeSopTemplate({...clone(D.networkSop||{id:NETWORK_SOP_ID,name:D.mainDefaults.auditDocument||'QUALITY OF SERVICE NETWORK AUDIT STANDARD OPERATING PROCEDURE',items:D.sopAudit||[]}),id:NETWORK_SOP_ID,builtin:true,source:'Built-in fallback'})}
liveModuleTemplates=fallbackModuleTemplates();repoSopTemplates=[fallbackNetworkSop()];
function builtinNetworkSop(){return clone(repoSopTemplates.find(t=>t.id===NETWORK_SOP_ID)||fallbackNetworkSop())}
function recordSopTemplate(record=state){if(record?.sopTemplate?.items?.length)return normalizeSopTemplate(record.sopTemplate);return builtinNetworkSop()}
function recordModuleTemplate(record,key){if(record?.moduleTemplates?.[key]?.items?.length)return normalizeModuleTemplate(key,record.moduleTemplates[key]);return normalizeModuleTemplate(key,liveModuleTemplates[key]||fallbackModuleTemplates()[key])}
function snapshotModuleTemplates(){return {wireless:clone(liveModuleTemplates.wireless),pcs:clone(liveModuleTemplates.pcs),wired:clone(liveModuleTemplates.wired)}}
async function refreshSopTemplates(){const custom=(await dbTemplateAll()).map(normalizeSopTemplate),repo=(repoSopTemplates||[]).map(normalizeSopTemplate);const ids=new Set(repo.map(t=>t.id));sopTemplates=[...repo,...custom.filter(t=>!ids.has(t.id))].sort((a,b)=>a.id===NETWORK_SOP_ID?-1:b.id===NETWORK_SOP_ID?1:a.name.localeCompare(b.name))}
function templateById(id){return sopTemplates.find(t=>t.id===id)||builtinNetworkSop()}
function templateByFingerprint(fp,record=state){const cur=record?recordSopTemplate(record):null;return (cur&&cur.fingerprint===fp?cur:null)||sopTemplates.find(t=>t.fingerprint===fp)||builtinNetworkSop()}
function newState(type='auditor'){const t=now(),sop=clone(builtinNetworkSop());return {id:uuid(),recordType:type,info:{stateOffice:'',auditDocument:sop.name,year:new Date().getFullYear(),auditDate:new Date().toISOString().slice(0,10),auditorName:'',auditeeName:'',reviewPeriod:''},sopTemplate:sop,moduleTemplates:snapshotModuleTemplates(),infoUpdatedAt:t,responses:{},sourceIds:[],finalStatus:type==='final'?'Draft':'',createdAt:t,updatedAt:t,deletedAt:null}}
function respKey(m,id){return m+'::'+id}
function getResp(m,id,record=state){const k=respKey(m,id);if(!record.responses)record.responses={};if(!record.responses[k])record.responses[k]={status:'',findingCategory:'',riskRating:'',evidence:'',auditorRemark:'',remark:'',photos:[],updatedAt:record.createdAt||now()};if(!record.responses[k].photos)record.responses[k].photos=[];return record.responses[k]}
function allItems(m,record=state){if(m==='sop'){const t=recordSopTemplate(record);return t.items.map((x,i)=>({...x,group:'SOP',_index:i}))}const t=recordModuleTemplate(record,m);return t.items.map((x,i)=>({...x,group:modules[m].title,_index:i}))}
function templateFingerprintKey(record){return [recordSopTemplate(record).fingerprint,...['wireless','pcs','wired'].map(k=>recordModuleTemplate(record,k).fingerprint)].join('|')}
function moduleStatsFor(record,m){const items=allItems(m,record);let c=0,n=0,na=0,p=0;for(const x of items){const s=getResp(m,x.id,record).status;if(s==='Complied')c++;else if(s==='Not Complied')n++;else if(s==='N/A')na++;else p++}return {total:items.length,c,n,na,p,done:c+n+na,score:pct(c,c+n)}}
function moduleStats(m){return moduleStatsFor(state,m)}
function totalStatsFor(record){let t={total:0,c:0,n:0,na:0,p:0,done:0};Object.keys(modules).forEach(m=>{const s=moduleStatsFor(record,m);Object.keys(t).forEach(k=>t[k]+=s[k]||0)});t.score=pct(t.c,t.c+t.n);return t}
function totalStats(){return totalStatsFor(state)}
function riskStatsFor(record){const out={Critical:0,High:0,Medium:0,Low:0,Unset:0};Object.keys(modules).forEach(m=>allItems(m,record).forEach(x=>{const r=getResp(m,x.id,record);if(r.status==='Not Complied'){if(out[r.riskRating]!==undefined)out[r.riskRating]++;else out.Unset++}}));return out}
function finalReadiness(record=state){let missingStatus=0,missingFinding=0;Object.keys(modules).forEach(m=>allItems(m,record).forEach(x=>{const r=getResp(m,x.id,record);if(!r.status)missingStatus++;if(r.status==='Not Complied'&&(!r.findingCategory||!r.riskRating||!String(r.auditorRemark||'').trim()))missingFinding++}));return {ready:missingStatus===0&&missingFinding===0,missingStatus,missingFinding}}
function isLocked(record=state){return !!(record&&record.recordType==='final'&&record.finalStatus==='Final')}
function isReadOnly(record=state){return !!(record&&(isLocked(record)||(record.recordType!=='final'&&record.importedAt)))}
async function refreshRecords(){records=(await dbAll()).filter(x=>!x.deletedAt).sort((a,b)=>ts(b.updatedAt)-ts(a.updatedAt));for(const id of [...compareSelection])if(!records.find(r=>r.id===id&&r.recordType!=='final'))compareSelection.delete(id)}
async function saveState(silent=true){if(!state)return;if(isReadOnly(state)){if(!silent)toast(state.importedAt?'Imported auditor source is read-only':'Final record is locked');return}state.updatedAt=now();await dbPut(state);await refreshRecords();if(!silent)toast('Saved')}
function renderTopbar(){document.getElementById('auditInfoBtn').style.display=state&&!isReadOnly(state)?'inline-block':'none'}
function render(){renderTopbar();document.getElementById('app').innerHTML=currentView==='dashboard'?dashboardHTML():currentView==='records'?recordsHTML():currentView==='team'?teamHTML():currentView==='home'?homeHTML():currentView==='module'?moduleHTML(currentModule):currentView==='sopManager'?sopManagerHTML():currentView==='review'?reviewHTML():currentView==='compare'?compareHTML():reconcileHTML()}

function dashboardHTML(){const localAudits=records.filter(r=>r.recordType!=='final'&&!r.importedAt).length,reviewCount=records.filter(r=>r.importedAt||r.recordType==='final').length;return `<section class="landing"><div class="landing-wrap"><img class="landing-logo" src="icon-192.png" alt="Audit QMOD"><div class="page-kicker">QMOD Audit Workspace</div><h1>Audit QMOD</h1><p class="landing-sub">Choose a workspace. Audits are stored offline on this device; Team Review is used after auditor results have been collected.</p><div class="landing-actions"><div class="landing-card" onclick="openMyAudits()"><div class="lc-icon">📋</div><h2>Perform Audit</h2><p>Create a new audit or continue an existing one. Complete SOP Audit, Wireless BAS, PCS and Wired BAS with remarks and photo evidence.</p><div class="lc-go">Open Audit → ${localAudits?`<span class="badge">${localAudits} record</span>`:''}</div></div><div class="landing-card" onclick="loadTeamReview()"><div class="lc-icon">🔎</div><h2>Review Audit</h2><p>Import multiple auditor results at once, highlight differences, review evidence, reconcile decisions and generate the final PDF / Word / Excel report.</p><div class="lc-go">Open Review → ${reviewCount?`<span class="badge">${reviewCount} item</span>`:''}</div></div></div></div></section>`}
function openMyAudits(){state=null;localStorage.removeItem(CURRENT_KEY);currentView='records';currentModule=null;render();scrollTo({top:0,behavior:'smooth'})}
function backToDashboard(){state=null;localStorage.removeItem(CURRENT_KEY);currentView='dashboard';currentModule=null;compareSelection.clear();render();scrollTo({top:0,behavior:'smooth'})}
function recordsHTML(){const localAudits=records.filter(r=>r.recordType!=='final'&&!r.importedAt);return `<div class="module-head"><button class="back" onclick="backToDashboard()">←</button><div><div class="page-kicker">Auditor Workspace</div><h1>Perform Audit</h1><p>Create a new audit or continue an audit stored on this device.</p></div><div class="module-tools"><button class="btn outline" onclick="openSopManager('records')">Audit Templates</button><button class="btn gold" onclick="createAudit()">+ New Audit</button></div></div><section class="summary-grid"><div class="panel kpi"><div class="n">${localAudits.length}</div><div class="l">Audit Records</div></div><div class="panel kpi"><div class="n">${localAudits.filter(r=>totalStatsFor(r).p===0).length}</div><div class="l">Checklist Completed</div></div><div class="panel kpi bad"><div class="n">${localAudits.reduce((n,r)=>n+totalStatsFor(r).n,0)}</div><div class="l">Total Findings</div></div><div class="panel kpi good"><div class="n">${localAudits.filter(r=>r.lastEmailPreparedAt).length}</div><div class="l">Results Prepared</div></div></section><div class="section-title"><div><h2>My Audit Records</h2><p>Autosaved locally. You can close the app and continue later.</p></div></div>${localAudits.length?`<section class="record-grid">${localAudits.map(recordCard).join('')}</section>`:`<div class="panel empty">No audits yet. Select <b>New Audit</b> to begin.</div>`}<div class="section-title"><div><h2>Backup</h2><p>Emergency backup for moving to another device or keeping an additional copy.</p></div></div><div class="panel" style="padding:16px;display:flex;gap:8px;flex-wrap:wrap"><button class="btn outline" onclick="exportAllBackup()">Export Backup</button><button class="btn outline" onclick="document.getElementById('backupFile').click()">Import Backup</button></div><div class="footer-note">Audit QMOD v5.7 • Repository-managed templates • Offline-first • Team review • Photo evidence</div>`}
function recordCard(r){const t=totalStatsFor(r),final=r.recordType==='final',locked=final&&r.finalStatus==='Final',imported=!!r.importedAt,emailed=!!r.lastEmailPreparedAt;const badges=`<span class="badge ${final?'final':''}">${final?(locked?'Final Report':'Final Review Draft'):(imported?'Auditor Source':'Auditor Record')}</span>${locked?'<span class="badge locked">LOCKED</span>':''}${imported?'<span class="badge imported">READ-ONLY IMPORT</span>':''}${emailed?'<span class="remote-badge">Email prepared</span>':''}`;return `<div class="panel record ${final?'final':''} ${imported?'imported':''}"><div class="score">${t.score}%</div><div>${badges}</div><div class="eyebrow" style="margin-top:8px">${esc(r.info.year||'—')}</div><h3>${esc(r.info.stateOffice||'Unnamed Audit')}</h3><p>${esc(r.info.auditorName||'Auditor not set')}<br>${esc(r.info.auditDate||'No audit date')} • ${t.done}/${t.total} completed • ${t.n} finding(s)</p><div class="stamp">Updated ${esc(fmtDate(r.updatedAt))}${emailed?' • email '+esc(fmtDate(r.lastEmailPreparedAt)):''}</div>${!final?`<label class="record-select"><input type="checkbox" ${compareSelection.has(r.id)?'checked':''} onchange="toggleCompareSelection('${r.id}',this.checked)"> Select for comparison</label>`:''}<div class="record-actions"><button class="btn primary small" onclick="openAuditRecord('${r.id}')">${locked?'Open Report':imported?'View Source':'Open / Continue'}</button>${!final&&!imported?`<button class="btn gold small" onclick="emailAuditResult('${r.id}')">Send Audit Result</button>`:''}${!final&&!imported?`<button class="btn outline small" onclick="exportAuditorSubmission('${r.id}')">Save .qmod</button>`:''}<button class="btn outline small" onclick="exportRecordBackup('${r.id}')">Backup</button><button class="btn danger small" onclick="deleteAuditRecord('${r.id}')">Delete</button></div></div>`}
function stateOverviewHTML(){const map={};for(const r of records){const s=r.info.stateOffice||'Unnamed';if(!map[s])map[s]={auditors:0,finals:0,locked:0,last:null};if(r.recordType==='final'){map[s].finals++;if(r.finalStatus==='Final'){map[s].locked++;if(!map[s].last||ts(r.finalisedAt)>ts(map[s].last.finalisedAt))map[s].last=r}}else map[s].auditors++}const entries=Object.entries(map);if(!entries.length)return '';return `<div class="section-title"><div><h2>State Office Overview</h2><p>Lightweight history view without background analytics.</p></div></div><section class="overview-grid">${entries.map(([s,v])=>`<div class="panel overview-card"><h4>${esc(s)}</h4><p>${v.auditors} auditor record(s) • ${v.finals} final review(s)</p><div class="big">${v.last?totalStatsFor(v.last).score+'%':'—'}</div><p>${v.last?'Latest final compliance':'No finalised report yet'}</p></div>`).join('')}</section>`}
async function createAudit(){await syncRepoTemplates();const r=newState('auditor');await dbPut(r);await refreshRecords();state=r;localStorage.setItem(CURRENT_KEY,r.id);currentView='home';render();openInfo()}
function openAuditRecord(id){state=records.find(x=>x.id===id)||null;if(!state)return;localStorage.setItem(CURRENT_KEY,id);currentView=state.recordType==='final'&&state.finalStatus!=='Final'&&state.sourceIds?.length?'reconcile':'home';currentModule=null;render();scrollTo({top:0,behavior:'smooth'})}
function backToRecords(){state=null;localStorage.removeItem(CURRENT_KEY);currentView='records';currentModule=null;render();scrollTo({top:0,behavior:'smooth'})}
function backToTeamReview(){state=null;localStorage.removeItem(CURRENT_KEY);currentView='team';currentModule=null;compareSelection.clear();render();scrollTo({top:0,behavior:'smooth'})}
function backFromRecord(){if(state&&(state.importedAt||state.recordType==='final'))backToTeamReview();else backToRecords()}
async function deleteAuditRecord(id){const ref=records.find(x=>x.recordType==='final'&&!x.deletedAt&&(x.sourceIds||[]).includes(id));if(ref){alert('This auditor record is still linked to a Final Review record. Delete the Final Review record first, or keep this source for evidence traceability.');return}if(!confirm('Delete this audit record from this device?'))return;let r=records.find(x=>x.id===id);if(!r)return;r=clone(r);r.deletedAt=now();r.updatedAt=r.deletedAt;await dbPut(r);if(state?.id===id)state=null;compareSelection.delete(id);await refreshRecords();currentView=(currentView==='team'||currentView==='compare'||currentView==='reconcile')?'team':'records';render()}
function isDemoRecord(r){return !!(r&&(r.demoData||r.importManifest?.demo||String(r.importManifest?.fileName||'').startsWith('DEMO_')))}
async function softDeleteRecordIds(ids){for(const id of ids){const original=records.find(r=>r.id===id);if(!original)continue;const r=clone(original);r.deletedAt=now();r.updatedAt=r.deletedAt;await dbPut(r);compareSelection.delete(id);if(state?.id===id)state=null}await refreshRecords()}
async function deleteReviewSource(id){const r=records.find(x=>x.id===id);if(!r)return;const linked=records.filter(x=>x.recordType==='final'&&!x.deletedAt&&(x.sourceIds||[]).includes(id));if(linked.length){alert(`This auditor result is linked to ${linked.length} Final Review record(s). Delete the linked Final Review record first.`);return}const label=`${r.info?.auditorName||'Auditor'} • ${r.info?.stateOffice||'Audit'} • ${r.info?.auditDate||''}`;if(!confirm(`Delete this auditor result from Review Audit?\n\n${label}\n\nThis only removes the local copy on this device.`))return;await softDeleteRecordIds([id]);currentView='team';render();toast('Auditor result deleted')}
async function deleteFinalReviewRecord(id){const r=records.find(x=>x.id===id&&x.recordType==='final');if(!r)return;const label=`${r.info?.stateOffice||'Audit'} • ${r.info?.auditDate||''}`;if(!confirm(`Delete this ${r.finalStatus==='Final'?'finalised report record':'Final Review draft'}?\n\n${label}\n\nSource auditor results will remain available.`))return;await softDeleteRecordIds([id]);currentView='team';render();toast('Final Review record deleted')}
async function purgeDemoData(ask=true){const demoSources=records.filter(r=>r.recordType!=='final'&&isDemoRecord(r));const demoIds=new Set(demoSources.map(r=>r.id));const demoFinals=records.filter(r=>r.recordType==='final'&&((r.sourceIds||[]).some(id=>demoIds.has(id))||r.demoData));const ids=[...demoSources,...demoFinals].map(r=>r.id);if(!ids.length){if(ask)toast('No demo data to delete');return true}if(ask&&!confirm(`Delete all demo/test data from this device?\n\n${demoSources.length} auditor result(s) and ${demoFinals.length} Final Review record(s) will be removed.`))return false;await softDeleteRecordIds(ids);currentView='team';compareSelection.clear();render();if(ask)toast('Demo data deleted');return true}

function toggleCompareSelection(id,on){if(on){if(compareSelection.size>=3){toast('Maximum 3 auditor records');render();return}compareSelection.add(id)}else compareSelection.delete(id);render()}
function clearCompareSelection(){compareSelection.clear();render()}
function selectedRecords(){return [...compareSelection].map(id=>records.find(r=>r.id===id)).filter(Boolean)}
function sameAuditIdentity(a,b){return (a.info.stateOffice||'')===(b.info.stateOffice||'')&&String(a.info.year||'')===String(b.info.year||'')&&(a.info.auditDocument||'')===(b.info.auditDocument||'')&&(a.info.auditDate||'')===(b.info.auditDate||'')&&templateFingerprintKey(a)===templateFingerprintKey(b)}
function startCompare(){const src=selectedRecords();if(src.length<2||src.length>3){alert('Select 2 or 3 auditor records.');return}if(!src.slice(1).every(r=>sameAuditIdentity(src[0],r))){alert('Comparison is only available for records with the same State Office, Year, Audit Document, Audit Date and audit template versions.');return}state=null;currentView='compare';compareFilter='differences';render();scrollTo({top:0,behavior:'smooth'})}
function homeHTML(){const t=totalStats(),risk=riskStatsFor(state),final=state.recordType==='final',locked=isLocked(state),sourceOnly=!!(state.importedAt&&!final),readonly=isReadOnly(state),ready=final?finalReadiness(state):null;return `<div style="margin-bottom:12px"><button class="btn outline small" onclick="backFromRecord()">← ${state&&(state.importedAt||state.recordType==='final')?'Review Audit':'My Audits'}</button></div><section class="hero"><div class="panel hero-main"><div class="eyebrow">${final?'Final Review Workspace':sourceOnly?'Imported Auditor Source':'Auditor Workspace'}</div><h1>${esc(state.info.stateOffice||'New Audit')}</h1><p>${esc(state.info.auditDocument||'Set audit information before starting the checklist.')}</p><div class="hero-actions">${!readonly?'<button class="btn gold" onclick="openInfo()">Edit Audit Info</button>':''}<button class="btn light" onclick="openReview()">${final?'Final Review & Report':sourceOnly?'View Result':'Review My Audit'}</button>${final&&state.sourceIds?.length&&!locked?'<button class="btn light" onclick="openReconcile()">Reconcile Sources</button>':''}${locked?'<button class="btn light" onclick="unlockFinal()">Unlock for Correction</button>':''}</div></div><div class="panel hero-meta"><div class="meta-grid"><div class="meta"><b>Audit Date</b><span>${esc(state.info.auditDate||'—')}</span></div><div class="meta"><b>Year</b><span>${esc(state.info.year||'—')}</span></div><div class="meta"><b>${final?'Reviewer(s)':'Auditor'}</b><span>${esc(state.info.auditorName||'Not set')}</span></div><div class="meta"><b>Overall Completion</b><span>${t.done}/${t.total} (${pct(t.done,t.total)}%)</span></div></div></div></section>${locked?'<div class="locked-note">✓ This final audit is locked. Report outputs reflect the finalised result.</div>':''}${sourceOnly?'<div class="locked-note">Imported team result is read-only. Original auditor judgement and evidence cannot be edited on the reviewer device.</div>':''}
${final&&!locked?readinessHTML(ready):''}<div class="section-title"><div><h2>Audit Modules</h2><p>${readonly?'Read-only checklist.':'SOP Audit uses the selected SOP template; Wireless BAS, PCS and Wired BAS use their dedicated checklists.'}</p></div></div><section class="modules">${Object.entries(modules).map(([k,m])=>moduleCard(k,m)).join('')}</section><div class="section-title"><div><h2>Current Result</h2><p>N/A and unanswered items are excluded from compliance score.</p></div></div><section class="summary-grid"><div class="panel kpi good"><div class="n">${t.c}</div><div class="l">Complied</div></div><div class="panel kpi bad"><div class="n">${t.n}</div><div class="l">Not Complied</div></div><div class="panel kpi"><div class="n">${t.p}</div><div class="l">Pending / Unanswered</div></div><div class="panel kpi"><div class="n">${t.score}%</div><div class="l">Compliance Score</div></div></section><div class="section-title"><div><h2>Finding Risk</h2><p>Based on current Not Complied items.</p></div></div><section class="overview-grid"><div class="panel overview-card"><h4>Critical</h4><div class="big">${risk.Critical}</div></div><div class="panel overview-card"><h4>High</h4><div class="big">${risk.High}</div></div><div class="panel overview-card"><h4>Medium</h4><div class="big">${risk.Medium}</div></div><div class="panel overview-card"><h4>Low</h4><div class="big">${risk.Low}</div></div></section><div class="section-title"><div><h2>${final?'Final Record':sourceOnly?'Imported Source':'This Auditor Record'}</h2><p>${sourceOnly?'Source retained for comparison and evidence traceability.':'Autosaved locally. Photos are compressed before storage.'}</p></div></div><div class="panel" style="padding:16px;display:flex;gap:8px;flex-wrap:wrap">${!final&&!sourceOnly?`<button class="btn gold" onclick="emailAuditResult(state.id)">Send Audit Result</button><button class="btn outline" onclick="exportAuditorSubmission(state.id)">Save .qmod</button>`:''}<button class="btn outline" onclick="exportBackup()">Backup This Record</button><button class="btn outline" onclick="document.getElementById('backupFile').click()">Import Backup</button></div>`}
function readinessHTML(r){return `<div class="readiness ${r.ready?'ready':'blocked'}"><h3>${r.ready?'✓ Ready to Finalise':'Final report quality gate'}</h3><p>${r.ready?'All checklist decisions are complete and all Not Complied findings have category, risk and auditor remark.':'Resolve '+r.missingStatus+' unanswered item(s) and '+r.missingFinding+' incomplete finding(s) before Finalise & Lock.'}</p>${r.ready?'<div style="margin-top:10px"><button class="btn primary" onclick="finaliseRecord()">Finalise & Lock</button></div>':''}</div>`}
function moduleCard(k,m){const s=moduleStats(k),desc=k==='sop'?recordSopTemplate(state).name:m.desc;return `<div class="panel module-card" onclick="openModule('${k}')"><div class="module-icon">${m.icon}</div><h3>${m.title}</h3><p>${esc(desc)}</p><div class="progress-row"><span>${s.done}/${s.total} completed</span><b>${pct(s.done,s.total)}%</b></div><div class="bar"><i style="width:${pct(s.done,s.total)}%"></i></div><div class="counts"><span class="count good">✓ ${s.c}</span><span class="count bad">✕ ${s.n}</span><span class="count">… ${s.p}</span></div></div>`}
function openModule(m){currentView='module';currentModule=m;filter='all';sectionFilter='all';render();scrollTo({top:0,behavior:'smooth'})}
