function moduleHTML(m){const mod=modules[m],s=moduleStats(m),items=allItems(m,state),sections=[...new Set(items.map(x=>x.group+' — '+x.section))],readonly=isReadOnly(state),sop=recordSopTemplate(state),mt=m==='sop'?sop:recordModuleTemplate(state,m);return `<div class="module-head"><button class="back" onclick="goHome()">←</button><div><h1>${mod.icon} ${mod.title}</h1><p>${m==='sop'?esc(sop.name)+' • ':''}${s.done}/${s.total} completed • ${s.n} finding(s) • score ${s.score}%</p></div><div class="module-tools">${!readonly?`<button class="btn outline" onclick="openSopManager('module')">Audit Templates</button>`:''}${!readonly?`<button class="btn outline" onclick="markVisible('Complied')">Mark visible Complied</button>`:''}<button class="btn primary" onclick="openReview()">Review</button></div></div><div class="callout"><b>Template snapshot:</b> ${esc(mt.name)}${mt.version?' • Version '+esc(mt.version):''}. This audit keeps this checklist snapshot even if the repository template is updated later.</div>${readonly?'<div class="locked-note">Read-only source/final record. Checklist decisions cannot be edited.</div>':''}<div class="sticky-tools"><div class="filter-row"><button class="chip ${filter==='all'?'active':''}" onclick="setFilter('all')">All</button><button class="chip ${filter==='pending'?'active':''}" onclick="setFilter('pending')">Unanswered</button><button class="chip ${filter==='nc'?'active':''}" onclick="setFilter('nc')">Not Complied</button><button class="chip ${filter==='done'?'active':''}" onclick="setFilter('done')">Completed</button></div><div class="filter-row" style="margin-top:7px"><button class="chip ${sectionFilter==='all'?'active':''}" onclick="setSection('all')">All Sections</button>${sections.map(x=>`<button class="chip ${sectionFilter===x?'active':''}" onclick='setSection(${JSON.stringify(x)})'>${esc(x)}</button>`).join('')}</div></div>${renderChecklist(m)}`}
function openSopManager(from='home'){sopManagerReturn=from;currentView='sopManager';currentModule=null;render();scrollTo({top:0,behavior:'smooth'})}
function closeSopManager(){if(sopManagerReturn==='module'){currentView='module';currentModule='sop'}else if(sopManagerReturn==='records'){state=null;currentView='records';currentModule=null}else{currentView='home';currentModule=null}render();scrollTo({top:0,behavior:'smooth'})}
function configuredTemplateForCatalog(name){return sopTemplates.find(t=>t.name.trim().toLowerCase()===String(name||'').trim().toLowerCase())}
function templateStatusCard(key,t){return `<div class="panel record"><div><span class="badge final">REPOSITORY</span>${state&&key!=='sop'&&recordModuleTemplate(state,key).fingerprint===t.fingerprint?'<span class="badge imported">CURRENT AUDIT</span>':''}</div><h3 style="margin-top:10px">${esc(t.name)}</h3><p>${t.items.length} audit check(s)${t.version?' • Version '+esc(t.version):''}</p><div class="stamp">${esc(t.source||repoTemplateMeta.source||'Repository master template')}</div></div>`}
function sopManagerHTML(){const current=state?recordSopTemplate(state):builtinNetworkSop(),catalog=(D.sopCatalog||[]),core=[['wireless',liveModuleTemplates.wireless],['pcs',liveModuleTemplates.pcs],['wired',liveModuleTemplates.wired]];return `<div class="module-head"><button class="back" onclick="closeSopManager()">←</button><div><div class="page-kicker">Repository Template Manager</div><h1>Audit Templates</h1><p>Edit one master Excel file in the GitHub repository. New audits automatically use the latest successfully loaded template.</p></div><div class="module-tools"><a class="btn outline" href="${MASTER_TEMPLATE_FILE}" download>Download Master Template</a><button class="btn gold" onclick="checkTemplateUpdates()">Check for Updates</button>${state&&!isReadOnly(state)?'<button class="btn primary" onclick="updateCurrentAuditTemplates()">Update This Audit</button>':''}</div></div><div class="callout"><b>Template source:</b> ${esc(repoTemplateMeta.source||MASTER_TEMPLATE_FILE)}${repoTemplateMeta.checkedAt?' • checked '+esc(fmtDate(repoTemplateMeta.checkedAt)):''}. Updating the repository workbook affects <b>new audits only</b>; existing audits keep the exact checklist snapshot used when they were created.</div><div class="section-title"><div><h2>Core Audit Templates</h2><p>SOP Audit, Wireless BAS, PCS and Wired BAS are data-driven from ${esc(MASTER_TEMPLATE_FILE)}.</p></div></div><section class="record-grid">${templateStatusCard('sop',builtinNetworkSop())}${core.map(([k,t])=>templateStatusCard(k,t)).join('')}</section><div class="section-title"><div><h2>Configured SOP Templates</h2><p>To publish another SOP for everyone, duplicate the SOP sheet in the master workbook, rename the sheet to start with <b>SOP -</b>, update its metadata/checklist, then replace the workbook in GitHub.</p></div><button class="btn outline" onclick="document.getElementById('sopTemplateFile').click()">Import Local SOP Template (Testing)</button></div><section class="record-grid">${sopTemplates.map(t=>`<div class="panel record"><div><span class="badge ${t.source==='Repository master template'||t.builtin?'final':''}">${t.source==='Repository master template'||t.builtin?'REPOSITORY':'LOCAL TEST'}</span>${state&&current.fingerprint===t.fingerprint?'<span class="badge imported">CURRENT AUDIT</span>':''}</div><h3 style="margin-top:10px">${esc(t.name)}</h3><p>${t.items.length} audit check(s)${t.version?' • Version '+esc(t.version):''}${t.code?' • '+esc(t.code):''}</p><div class="record-actions">${state&&!isReadOnly(state)?`<button class="btn primary small" onclick="selectSopTemplate('${esc(t.id)}')">Use for This Audit</button>`:''}${t.source!=='Repository master template'&&!t.builtin?`<button class="btn danger small" onclick="deleteSopTemplate('${esc(t.id)}')">Delete Local Template</button>`:''}</div></div>`).join('')}</section><div class="section-title"><div><h2>SOP Catalogue</h2><p>Unconfigured SOPs remain unavailable until added to the repository master workbook or imported locally for testing.</p></div></div><div class="panel" style="padding:8px 16px">${catalog.map(c=>{const t=configuredTemplateForCatalog(c.name);return `<div style="display:flex;gap:12px;align-items:center;padding:13px 2px;border-bottom:1px solid var(--line)"><div style="flex:1;min-width:0"><b>${esc(c.name)}</b><div class="small" style="margin-top:3px">${t?t.items.length+' configured audit checks':'Not yet configured'}</div></div>${t?'<span class="status-tag good">Configured</span>':'<span class="status-tag pending">Not Configured Yet</span>'}</div>`}).join('')}</div>`}

async function updateCurrentAuditTemplates(){if(!state||isReadOnly(state))return;await syncRepoTemplates();const currentSop=recordSopTemplate(state),latestSop=sopTemplates.find(t=>t.id===currentSop.id);const hasData=Object.values(state.responses||{}).some(v=>v&&(v.status||v.auditorRemark||v.evidence||(v.photos||[]).length));if(hasData&&!confirm('Update this in-progress audit to the latest repository templates? Existing responses with the same Item ID will be kept. New checklist items will appear unanswered, and removed items will no longer be shown.'))return;if(latestSop)state.sopTemplate=clone(latestSop);state.moduleTemplates=snapshotModuleTemplates();state.infoUpdatedAt=now();await saveState(false);render();toast('This audit now uses the latest repository templates')}
async function selectSopTemplate(id){if(!state||isReadOnly(state))return;const next=templateById(id),old=recordSopTemplate(state);if(next.fingerprint===old.fingerprint){toast('This SOP template is already selected');return}const hasSopData=Object.entries(state.responses||{}).some(([k,v])=>k.startsWith('sop::')&&v&&(v.status||v.auditorRemark||v.evidence||(v.photos||[]).length));if(hasSopData&&!confirm('Use this SOP template for the current audit? Existing SOP responses will remain stored but will no longer appear in the active checklist.'))return;state.sopTemplate=clone(next);if(!state.info.auditDocument||state.info.auditDocument===old.name)state.info.auditDocument=next.name;state.infoUpdatedAt=now();await saveState(false);currentView='home';currentModule=null;render();toast('SOP template selected')}
async function deleteSopTemplate(id){const t=sopTemplates.find(x=>x.id===id);if(!t||t.builtin)return;if(!confirm(`Delete the template "${t.name}" from this device? Existing audit records keep their own checklist snapshot.`))return;await dbTemplateDelete(id);await refreshSopTemplates();render();toast('SOP template deleted')}
function zipU16(d,o){return d.getUint16(o,true)} function zipU32(d,o){return d.getUint32(o,true)}
async function inflateRaw(bytes){if(typeof DecompressionStream==='undefined')throw new Error('This browser cannot read .xlsx templates. Use a current Chrome, Edge or Safari browser.');const ds=new DecompressionStream('deflate-raw'),stream=new Blob([bytes]).stream().pipeThrough(ds);return new Uint8Array(await new Response(stream).arrayBuffer())}
async function unzipXlsx(buffer){const u8=new Uint8Array(buffer),dv=new DataView(buffer);let eocd=-1;for(let i=u8.length-22;i>=Math.max(0,u8.length-65557);i--){if(zipU32(dv,i)===0x06054b50){eocd=i;break}}if(eocd<0)throw new Error('Invalid XLSX file.');const count=zipU16(dv,eocd+10),cdOffset=zipU32(dv,eocd+16),dec=new TextDecoder('utf-8'),out=new Map();let p=cdOffset;for(let n=0;n<count;n++){if(zipU32(dv,p)!==0x02014b50)throw new Error('Invalid XLSX directory.');const method=zipU16(dv,p+10),csize=zipU32(dv,p+20),nameLen=zipU16(dv,p+28),extraLen=zipU16(dv,p+30),commentLen=zipU16(dv,p+32),localOffset=zipU32(dv,p+42),name=dec.decode(u8.slice(p+46,p+46+nameLen));if(zipU32(dv,localOffset)!==0x04034b50)throw new Error('Invalid XLSX entry.');const localNameLen=zipU16(dv,localOffset+26),localExtraLen=zipU16(dv,localOffset+28),start=localOffset+30+localNameLen+localExtraLen,comp=u8.slice(start,start+csize);let data;if(method===0)data=comp;else if(method===8)data=await inflateRaw(comp);else throw new Error('Unsupported XLSX compression method.');out.set(name,data);p+=46+nameLen+extraLen+commentLen}return out}
function xmlDoc(entries,path){const b=entries.get(path);if(!b)return null;return new DOMParser().parseFromString(new TextDecoder('utf-8').decode(b),'application/xml')}
function xmlEls(node,name){return [...node.getElementsByTagNameNS('*',name)]}
function relId(el){for(const a of [...el.attributes])if(a.localName==='id')return a.value;return ''}
function xlsxSharedStrings(entries){const doc=xmlDoc(entries,'xl/sharedStrings.xml');if(!doc)return [];return xmlEls(doc,'si').map(si=>xmlEls(si,'t').map(t=>t.textContent||'').join(''))}
function colIndex(ref){const m=String(ref||'').match(/^([A-Z]+)/i);if(!m)return 0;let n=0;for(const ch of m[1].toUpperCase())n=n*26+ch.charCodeAt(0)-64;return n-1}
function sheetGrid(doc,shared){const rows=[];if(!doc)return rows;for(const c of xmlEls(doc,'c')){const ref=c.getAttribute('r')||'',rm=ref.match(/(\d+)$/);if(!rm)continue;const r=Number(rm[1])-1,col=colIndex(ref),t=c.getAttribute('t')||'';let val='';if(t==='inlineStr'){val=xmlEls(c,'t').map(x=>x.textContent||'').join('')}else{const v=xmlEls(c,'v')[0]?.textContent??'';if(t==='s')val=shared[Number(v)]??'';else if(t==='b')val=v==='1'?'TRUE':'FALSE';else val=v}if(!rows[r])rows[r]=[];rows[r][col]=val}return rows}
async function readSopWorkbook(file){const entries=await unzipXlsx(await file.arrayBuffer()),wb=xmlDoc(entries,'xl/workbook.xml'),rels=xmlDoc(entries,'xl/_rels/workbook.xml.rels');if(!wb||!rels)throw new Error('Workbook structure is incomplete.');const relMap={};for(const r of xmlEls(rels,'Relationship'))relMap[r.getAttribute('Id')]=r.getAttribute('Target');const sheets=xmlEls(wb,'sheet'),chosen=sheets.find(s=>String(s.getAttribute('name')||'').toLowerCase()==='sop audit')||sheets[0];if(!chosen)throw new Error('No worksheet found.');const target=relMap[relId(chosen)];if(!target)throw new Error('Worksheet relationship not found.');const path=target.startsWith('/')?target.slice(1):'xl/'+target.replace(/^\.\//,'');return sheetGrid(xmlDoc(entries,path),xlsxSharedStrings(entries))}
async function readWorkbookSheets(source){const entries=await unzipXlsx(await source.arrayBuffer()),wb=xmlDoc(entries,'xl/workbook.xml'),rels=xmlDoc(entries,'xl/_rels/workbook.xml.rels');if(!wb||!rels)throw new Error('Workbook structure is incomplete.');const relMap={};for(const r of xmlEls(rels,'Relationship'))relMap[r.getAttribute('Id')]=r.getAttribute('Target');const shared=xlsxSharedStrings(entries),out={};for(const sh of xmlEls(wb,'sheet')){const name=String(sh.getAttribute('name')||''),target=relMap[relId(sh)];if(!name||!target)continue;const path=target.startsWith('/')?target.slice(1):'xl/'+target.replace(/^\.\//,'');out[name]=sheetGrid(xmlDoc(entries,path),shared)}return out}
function parseRepoTemplateGrid(grid,sheetName){let type='',id='',name='',version='',effectiveDate='',sourceRef='';for(let r=0;r<Math.min(grid.length,12);r++){const label=cleanCell(grid[r]?.[0]).toLowerCase(),v=cleanCell(grid[r]?.[1]);if(label==='template type')type=v.toUpperCase();else if(label==='template id')id=v;else if(label==='template name')name=v;else if(label==='template version')version=v;else if(label==='effective date')effectiveDate=v;else if(label.startsWith('source'))sourceRef=v}let header=-1,cols={};for(let r=0;r<Math.min(grid.length,30);r++){const vals=(grid[r]||[]).map(x=>cleanCell(x).toLowerCase()),sec=vals.findIndex(x=>x==='section'),chk=vals.findIndex(x=>x==='audit check'||x==='requirement'||x==='audit requirement');if(sec>=0&&chk>=0){header=r;cols={id:vals.findIndex(x=>x==='item id'||x==='id'),section:sec,check:chk,evidence:vals.findIndex(x=>x==='evidence expected'||x==='evidence'),active:vals.findIndex(x=>x==='active')};break}}if(header<0)throw new Error('No checklist header found in '+sheetName);const items=[];for(let r=header+1;r<grid.length;r++){const row=grid[r]||[],check=cleanCell(row[cols.check]),section=cleanCell(row[cols.section]),active=cols.active>=0?cleanCell(row[cols.active]).toLowerCase():'yes';if(!check||check.toLowerCase()==='total'||['no','n','false','0','inactive'].includes(active))continue;items.push({id:cols.id>=0?cleanCell(row[cols.id]):'',section:section||'General',check,evidenceExpected:cols.evidence>=0?cleanCell(row[cols.evidence]):''})}if(!items.length)throw new Error('No active checklist rows found in '+sheetName);return {type:type||(/^sop(?:\s|-)/i.test(sheetName)?'SOP':'MODULE'),id:id||slug(name||sheetName),name:name||sheetName,version,effectiveDate,sourceRef,source:'Repository master template',items}}
function buildRepoPack(sheets){const pack={modules:{},sops:[],loadedAt:now(),source:MASTER_TEMPLATE_FILE};for(const [sheetName,grid] of Object.entries(sheets)){if(sheetName.toLowerCase()==='readme')continue;let raw;try{raw=parseRepoTemplateGrid(grid,sheetName)}catch(e){console.warn('Template sheet skipped',sheetName,e);continue}const low=sheetName.trim().toLowerCase();if(raw.type==='SOP'||low==='sop audit'||low.startsWith('sop -')){if(low==='sop audit')raw.id=NETWORK_SOP_ID;pack.sops.push(normalizeSopTemplate(raw));continue}if(low==='wireless bas')pack.modules.wireless=normalizeModuleTemplate('wireless',raw);else if(low==='pcs')pack.modules.pcs=normalizeModuleTemplate('pcs',raw);else if(low==='wired bas')pack.modules.wired=normalizeModuleTemplate('wired',raw)}if(!pack.sops.length)throw new Error('SOP Audit template is missing.');for(const k of ['wireless','pcs','wired'])if(!pack.modules[k])throw new Error(modules[k].title+' template is missing.');return pack}
function applyRepoPack(pack,sourceLabel='Repository master template'){if(!pack?.modules||!pack?.sops?.length)return false;liveModuleTemplates={wireless:normalizeModuleTemplate('wireless',pack.modules.wireless),pcs:normalizeModuleTemplate('pcs',pack.modules.pcs),wired:normalizeModuleTemplate('wired',pack.modules.wired)};repoSopTemplates=pack.sops.map(t=>normalizeSopTemplate({...t,source:sourceLabel,builtin:t.id===NETWORK_SOP_ID}));repoTemplateMeta={source:sourceLabel,checkedAt:pack.loadedAt||now(),updated:true};return true}
function loadCachedRepoPack(){try{const pack=JSON.parse(localStorage.getItem(REPO_TEMPLATE_CACHE_KEY)||'null');if(pack&&applyRepoPack(pack,'Cached repository template'))return true}catch(e){console.warn('Cached template pack could not be loaded',e)}return false}
async function syncRepoTemplates({notify=false}={}){try{const res=await fetch(MASTER_TEMPLATE_FILE,{cache:'no-store'});if(!res.ok)throw new Error('HTTP '+res.status);const pack=buildRepoPack(await readWorkbookSheets(res));localStorage.setItem(REPO_TEMPLATE_CACHE_KEY,JSON.stringify(pack));applyRepoPack(pack,'Repository master template');await refreshSopTemplates();if(notify){render();toast('Latest repository templates loaded')}return true}catch(e){console.warn('Repository template update unavailable',e);if(notify)alert(`Could not load the latest repository template. Audit QMOD will continue using the most recently cached template.

${e?.message||e}`);return false}}
async function checkTemplateUpdates(){await syncRepoTemplates({notify:true})}
async function migrateModuleTemplateSnapshots(){const all=await dbAll(),fallback=fallbackModuleTemplates();let changed=0;for(const r of all){if(!r.moduleTemplates){r.moduleTemplates=clone(fallback);r.updatedAt=r.updatedAt||now();await dbPut(r);changed++}}return changed}
function cleanCell(v){return String(v??'').replace(/\s+/g,' ').trim()}
function parseSopGrid(grid){let name='',code='',version='',effectiveDate='';for(let r=0;r<Math.min(grid.length,12);r++){const label=cleanCell(grid[r]?.[0]).toLowerCase(),v=cleanCell(grid[r]?.[1]);if(label==='sop name')name=v;else if(label.startsWith('sop code'))code=v;else if(label.startsWith('sop version'))version=v;else if(label==='effective date')effectiveDate=v}let header=-1,cols={};for(let r=0;r<Math.min(grid.length,30);r++){const vals=(grid[r]||[]).map(x=>cleanCell(x).toLowerCase());const sec=vals.findIndex(x=>x==='section'),chk=vals.findIndex(x=>x==='audit check'||x==='requirement'||x==='audit requirement');if(sec>=0&&chk>=0){header=r;cols={section:sec,check:chk,evidence:vals.findIndex(x=>x==='evidence expected'||x==='evidence'),active:vals.findIndex(x=>x==='active')};break}}const raw=[];if(header>=0){for(let r=header+1;r<grid.length;r++){const row=grid[r]||[],section=cleanCell(row[cols.section]),check=cleanCell(row[cols.check]),active=cols.active>=0?cleanCell(row[cols.active]).toLowerCase():'yes';if(!check)continue;if(['no','n','false','0','inactive'].includes(active))continue;raw.push({section:section||'General',check,evidenceExpected:cols.evidence>=0?cleanCell(row[cols.evidence]):''})}}else{let section='General';for(let r=0;r<grid.length;r++){const a=cleanCell(grid[r]?.[0]),b=cleanCell(grid[r]?.[1]);if(a&&!b&&!/^\d+$/.test(a)){section=a;continue}if(b&&(/^\d+$/.test(a)||a===''))raw.push({section,check:b,evidenceExpected:cleanCell(grid[r]?.[6])})}}if(!raw.length)throw new Error('No audit checklist rows were found. Use the Audit QMOD SOP Template format.');if(!name)name=prompt('SOP Name was not found in the workbook. Enter the SOP name:','')||'';name=cleanCell(name);if(!name)throw new Error('SOP Name is required.');const id='sop-'+slug(name),items=raw.map((x,i)=>({id:'SOPC-'+hashString(name+'|'+x.section+'|'+x.check),section:x.section,check:x.check,evidenceExpected:x.evidenceExpected,sourceNo:i+1}));return normalizeSopTemplate({id,name,code,version,effectiveDate,items,builtin:false,importedAt:now()})}
async function importSopTemplate(ev){const file=ev.target.files?.[0];if(!file)return;try{const grid=await readSopWorkbook(file),t=parseSopGrid(grid);if(t.name.trim().toLowerCase()===builtinNetworkSop().name.trim().toLowerCase()){throw new Error('This SOP name is already provided as the built-in Network Audit template. Change SOP Name in the Excel file when creating another SOP.')}const existing=sopTemplates.find(x=>x.id===t.id&&!x.builtin);if(existing&&!confirm(`Replace the configured template "${existing.name}" with this imported version? Existing audits will not change.`)){ev.target.value='';return}await dbTemplatePut(t);await refreshSopTemplates();render();toast(`${t.name} imported • ${t.items.length} checks`)}catch(e){console.error(e);alert('Could not import SOP template. '+(e?.message||e))}finally{ev.target.value=''}}

function setFilter(f){filter=f;render()} function setSection(s){sectionFilter=s;render()}
function visibleItems(m){return allItems(m,state).filter(x=>{const r=getResp(m,x.id),fs=filter==='all'||(filter==='pending'&&!r.status)||(filter==='nc'&&r.status==='Not Complied')||(filter==='done'&&!!r.status),ss=sectionFilter==='all'||sectionFilter===(x.group+' — '+x.section);return fs&&ss})}
function renderChecklist(m){const arr=visibleItems(m);if(!arr.length)return `<div class="panel empty">No checklist item matches this filter.</div>`;let html='',last='';for(const x of arr){const label=x.group+' — '+x.section;if(label!==last){if(last)html+='</div>';const total=allItems(m,state).filter(z=>z.group===x.group&&z.section===x.section).length;html+=`<div class="section-block"><div class="section-header"><h3>${esc(label)}</h3><span>${total} item(s)</span></div>`;last=label}html+=checkCard(m,x)}return html+'</div>'}
function photoHTML(m,id,r){if(!r.photos?.length)return '<div class="photo-note">No photo evidence attached.</div>';return `<div class="photos">${r.photos.map(p=>`<div class="photo"><img src="${p.dataUrl}" alt="evidence" onclick="showRecordPhoto('${state.id}','${m}','${id}','${p.id}')" style="cursor:pointer"><div class="pn">${esc(p.name)}</div>${!isReadOnly(state)?`<button onclick="removePhoto('${m}','${id}','${p.id}')">Remove</button>`:''}</div>`).join('')}</div>`}
function checkCard(m,x){const r=getResp(m,x.id),open=r.status==='Not Complied'||r.photos?.length,locked=isReadOnly(state),dis=locked?'disabled':'';return `<div class="check-card" data-id="${esc(x.id)}"><div class="check-top"><div class="num">${esc(x.id.replace(/^.*?-/,''))}</div><div><div class="check-text">${esc(x.check)}</div><div class="expected"><b>Evidence expected:</b> ${esc(x.evidenceExpected||'—')}</div>${x.sampleId?`<div class="expected"><b>Sample ID:</b> ${esc(x.sampleId)}</div>`:''}</div><div class="status-buttons"><button ${dis} class="status complied ${r.status==='Complied'?'selected':''}" onclick="setStatus('${m}','${x.id}','Complied')">✓ Complied</button><button ${dis} class="status not ${r.status==='Not Complied'?'selected':''}" onclick="setStatus('${m}','${x.id}','Not Complied')">✕ Not Complied</button><button ${dis} class="status na ${r.status==='N/A'?'selected':''}" onclick="setStatus('${m}','${x.id}','N/A')">N/A</button></div></div><button class="details-toggle" onclick="toggleDetails(this)">${r.photos?.length?`Evidence / remark • ${r.photos.length} photo(s)`:(open?'Finding / evidence details':'Add evidence / remark')} ▾</button><div class="details ${open?'open':''}"><div class="form-grid ${r.status==='Not Complied'?'finding-required':''}"><div class="field"><label>Finding Category</label><select ${dis} onchange="updateResp('${m}','${x.id}','findingCategory',this.value)"><option value="">Select…</option>${opts(D.dropdowns.findingCategory,r.findingCategory)}</select></div><div class="field"><label>Risk Rating</label><select ${dis} onchange="updateResp('${m}','${x.id}','riskRating',this.value)"><option value="">Select…</option>${opts(D.dropdowns.riskRating,r.riskRating)}</select></div><div class="field full"><label>Evidence Link / Reference</label><input ${dis} value="${esc(r.evidence)}" placeholder="Document ref, filename, SharePoint link…" onchange="updateResp('${m}','${x.id}','evidence',this.value)"></div><div class="field full"><label>Photo Evidence</label>${!locked?`<div class="photo-tools"><label class="btn primary small photo-action" style="display:inline-flex;align-items:center;justify-content:center;cursor:pointer">📷 Take Photo<input type="file" accept="image/*" capture="environment" hidden onchange="addPhotos('${m}','${x.id}',this.files);this.value='' "></label><label class="btn outline small photo-action" style="display:inline-flex;align-items:center;justify-content:center;cursor:pointer">🖼 Choose Photos<input type="file" accept="image/*" multiple hidden onchange="addPhotos('${m}','${x.id}',this.files);this.value='' "></label><span class="photo-note">Up to 6 photos per item. Images are compressed automatically.</span></div>`:''}${photoHTML(m,x.id,r)}</div><div class="field full"><label>Auditor Remark</label><textarea ${dis} placeholder="Audit observation / justification…" onchange="updateResp('${m}','${x.id}','auditorRemark',this.value)">${esc(r.auditorRemark)}</textarea></div><div class="field full"><label>Additional Remark / Follow-up</label><textarea ${dis} placeholder="Corrective action / follow-up note…" onchange="updateResp('${m}','${x.id}','remark',this.value)">${esc(r.remark)}</textarea></div></div></div></div>`}
function opts(arr,val){return (arr||[]).map(x=>`<option ${x===val?'selected':''}>${esc(x)}</option>`).join('')}
function toggleDetails(b){b.nextElementSibling.classList.toggle('open')}
async function setStatus(m,id,status){if(isReadOnly(state))return;const r=getResp(m,id);r.status=(r.status===status?'':status);if(r.status==='Complied')r.findingCategory=r.findingCategory||'No Finding';r.updatedAt=now();await saveState();render()}
async function updateResp(m,id,k,v){if(isReadOnly(state))return;const r=getResp(m,id);r[k]=v;r.updatedAt=now();await saveState()}
async function markVisible(status){if(isReadOnly(state))return;for(const x of visibleItems(currentModule)){const r=getResp(currentModule,x.id);r.status=status;r.updatedAt=now()}await saveState(false);render()}
async function compressImage(file){return new Promise((resolve,reject)=>{const rd=new FileReader();rd.onload=()=>{const img=new Image();img.onload=()=>{const max=1000,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',0.68))};img.onerror=reject;img.src=rd.result};rd.onerror=reject;rd.readAsDataURL(file)})}
async function addPhotos(m,id,fileList){if(isReadOnly(state))return;const r=getResp(m,id),files=[...fileList];if(r.photos.length>=6){alert('Maximum 6 photos per checklist item.');return}for(const f of files.slice(0,6-r.photos.length)){try{const dataUrl=await compressImage(f);r.photos.push({id:uuid(),name:f.name||'evidence.jpg',dataUrl,createdAt:now()})}catch(e){alert('Unable to process '+f.name)}}r.updatedAt=now();await saveState(false);render()}
async function removePhoto(m,id,pid){if(isReadOnly(state))return;const r=getResp(m,id);r.photos=(r.photos||[]).filter(p=>p.id!==pid);r.updatedAt=now();await saveState(false);render()}

function sectionStatsFor(record,m){const map=new Map();for(const x of allItems(m,record)){if(!map.has(x.section))map.set(x.section,{section:x.section,c:0,n:0,na:0,p:0});const o=map.get(x.section),st=getResp(m,x.id,record).status;if(st==='Complied')o.c++;else if(st==='Not Complied')o.n++;else if(st==='N/A')o.na++;else o.p++}return [...map.values()].map(o=>({...o,score:pct(o.c,o.c+o.n)}))}
function keyFindingSummary(record=state){const lines=[];for(const [m,def] of Object.entries(modules)){const nc=allItems(m,record).map(x=>({x,r:getResp(m,x.id,record)})).filter(z=>z.r.status==='Not Complied');if(!nc.length)continue;const bySec={};nc.forEach(z=>bySec[z.x.section]=(bySec[z.x.section]||0)+1);const top=Object.entries(bySec).sort((a,b)=>b[1]-a[1]).slice(0,2).map(x=>x[0]).join(' / '),remark=nc.map(z=>String(z.r.auditorRemark||'').trim()).find(Boolean),fallback=nc[0].x.check;lines.push(`${def.title} – ${nc.length} compliance gap${nc.length===1?'':'s'} identified under ${top||'the reviewed checklist'}. ${remark||fallback}`)}return lines}
function auditConclusion(record=state){const t=totalStatsFor(record),risk=riskStatsFor(record);if(t.n===0&&t.p===0)return 'Fully Compliant';if(risk.Critical>0||t.score<80)return 'Partially Compliant – Significant Improvement Required';if(risk.High>0||t.score<90)return 'Generally Compliant – Improvement Required';return 'Generally Compliant – Minor Improvement Required'}
function auditResultDashboardHTML(record=state,printMode=false){const cards=Object.entries(modules).map(([m,def])=>{const rows=sectionStatsFor(record,m);return `<div class="result-module"><h3>${esc(def.title)} Compliance Rate</h3>${rows.map(x=>`<div class="result-row"><div class="result-label">${esc(x.section)}</div><div class="result-track"><div class="result-bar" style="width:${x.score}%"></div><span>${x.score.toFixed?x.score.toFixed(2):Number(x.score).toFixed(2)}%</span></div></div>`).join('')}</div>`}).join(''),findings=keyFindingSummary(record),conclusion=auditConclusion(record);return `<section class="overall-result ${printMode?'print-result':''}"><div class="overall-title"><span>1</span> Overall Audit Result for Audit Compliance at ${esc(record.info.stateOffice||'State Office')}</div><div class="result-modules">${cards}</div><div class="result-summary"><b>Key Finding Summary:</b>${findings.length?`<ul>${findings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>No non-compliance findings were identified.</p>'}<b>Conclusion:</b><p>${esc(conclusion)}</p></div></section>`}
function reviewHTML(){const t=totalStats(),findings=[];Object.keys(modules).forEach(m=>allItems(m,state).forEach(x=>{const r=getResp(m,x.id);if(r.status==='Not Complied')findings.push({m,x,r})}));const final=state.recordType==='final',locked=isLocked(state),sourceOnly=!!(state.importedAt&&!final),ready=final?finalReadiness(state):null;let actions='';if(!final&&!sourceOnly)actions=`<button class="btn gold" onclick="emailAuditResult(state.id)">Send Audit Result</button><button class="btn outline" onclick="exportAuditorSubmission(state.id)">Save .qmod</button>`;else if(locked)actions='<button class="btn outline" onclick="exportExcel()">Excel</button><button class="btn outline" onclick="exportWord()">Word</button><button class="btn gold" onclick="printReport()">PDF / Print</button>';else if(final)actions='<button class="btn primary" onclick="openReconcile()">Continue Reconciliation</button>';return `<div class="module-head"><button class="back" onclick="goHome()">←</button><div><h1>${final?'Final Review & Report':sourceOnly?'Auditor Source Result':'Review My Audit'}</h1><p>${esc(state.info.stateOffice||'Audit')} • ${esc(state.info.auditDate||'')}</p></div><div class="module-tools">${actions}</div></div>${final&&!locked?readinessHTML(ready):''}${!final&&!sourceOnly?`<div class="callout">When the audit is complete, select <b>Send Audit Result</b>. Final Excel/Word/PDF reports are generated only from a reconciled Final Review record.</div>`:''}${sourceOnly?'<div class="callout">Read-only auditor submission. Use Team Review to compare it with other auditor results.</div>':''}${locked?'<div class="locked-note">✓ Finalised and locked '+esc(fmtDate(state.finalisedAt))+'</div>':''}${final?auditResultDashboardHTML(state):''}<section class="summary-grid"><div class="panel kpi good"><div class="n">${t.c}</div><div class="l">Complied</div></div><div class="panel kpi bad"><div class="n">${t.n}</div><div class="l">Findings</div></div><div class="panel kpi"><div class="n">${t.p}</div><div class="l">Unanswered</div></div><div class="panel kpi"><div class="n">${t.score}%</div><div class="l">Overall Compliance</div></div></section><div class="section-title"><div><h2>Non-Compliance Findings</h2><p>Photo count is shown for each finding.</p></div></div><div class="panel review-list">${findings.length?findings.map(f=>`<div class="finding-row"><div><b>${esc(modules[f.m].title)}</b><div class="small">${esc(f.x.id)}</div></div><div><b>${esc(f.x.check)}</b><div class="small">${esc(f.r.auditorRemark||'No auditor remark')} • ${f.r.photos?.length||0} photo(s)</div></div><div><span class="risk">${esc(f.r.findingCategory||'Category not set')}</span></div><div><span class="risk">${esc(f.r.riskRating||'Risk not set')}</span></div></div>`).join(''):`<div class="empty">No non-compliance findings recorded.</div>`}</div><div class="section-title"><div><h2>Module Completion</h2></div></div><section class="modules">${Object.entries(modules).map(([k,m])=>moduleCard(k,m)).join('')}</section>`}
function comparisonRows(src=selectedRecords()){const rows=[];const basis=src[0]||state;Object.keys(modules).forEach(m=>allItems(m,basis).forEach(x=>{const rs=src.map(s=>getResp(m,x.id,s)),statuses=rs.map(r=>r.status||'Unanswered'),unique=[...new Set(statuses)],disagree=unique.length>1,allBlank=statuses.every(s=>s==='Unanswered'),anyNC=statuses.includes('Not Complied');rows.push({m,x,rs,statuses,disagree,allBlank,anyNC})}));return rows}
function compareHTML(){const src=selectedRecords();if(src.length<2)return `<div class="panel empty">Comparison selection is no longer available. <button class="btn outline" onclick="backToTeamReview()">Back</button></div>`;const rows=comparisonRows(src),dis=rows.filter(r=>r.disagree).length,agree=rows.filter(r=>!r.disagree&&!r.allBlank).length,allblank=rows.filter(r=>r.allBlank).length;const shown=rows.filter(r=>compareFilter==='all'||(compareFilter==='differences'&&r.disagree)||(compareFilter==='nc'&&r.anyNC));return `<div class="module-head"><button class="back" onclick="backToTeamReview()">←</button><div><h1>Compare Auditor Results</h1><p>${esc(src[0].info.stateOffice)} • ${src.length} auditors • ${esc(recordSopTemplate(src[0]).name)} • human review before final decision</p></div><div class="module-tools"><button class="btn gold" onclick="createFinalFromCompare()">Create Final Review Record</button></div></div><section class="summary-grid"><div class="panel kpi good"><div class="n">${agree}</div><div class="l">Agreed Items</div></div><div class="panel kpi bad"><div class="n">${dis}</div><div class="l">Different Decisions</div></div><div class="panel kpi"><div class="n">${allblank}</div><div class="l">All Unanswered</div></div><div class="panel kpi"><div class="n">${rows.length}</div><div class="l">Total Checks</div></div></section><div class="section-title"><div><h2>Auditor Sources</h2><p>Scores remain separate; nothing is overwritten.</p></div></div><div class="source-grid">${src.map(sourceSummaryCard).join('')}</div><div class="sticky-tools"><div class="filter-row"><button class="chip ${compareFilter==='differences'?'active':''}" onclick="setCompareFilter('differences')">Differences (${dis})</button><button class="chip ${compareFilter==='nc'?'active':''}" onclick="setCompareFilter('nc')">Any Not Complied</button><button class="chip ${compareFilter==='all'?'active':''}" onclick="setCompareFilter('all')">All Items</button></div></div>${shown.length?shown.map(r=>compareItemHTML(r,src,false)).join(''):'<div class="panel empty">No item matches this filter.</div>'}`}
function sourceSummaryCard(r){const t=totalStatsFor(r);return `<div class="source-card"><h4>${esc(r.info.auditorName||'Unnamed auditor')}</h4><span class="status-tag">${t.score}% score</span><div class="meta-line">${t.c} complied • ${t.n} NC • ${t.p} unanswered</div><div class="meta-line">Updated ${esc(fmtDate(r.updatedAt))}</div></div>`}
function setCompareFilter(f){compareFilter=f;render()}
function statusTag(s){const cls=s==='Complied'?'good':s==='Not Complied'?'bad':s==='N/A'?'na':'pending';return `<span class="status-tag ${cls}">${esc(s||'Unanswered')}</span>`}
function sourceEvidenceCard(src,m,x,r,withActions=false){return `<div class="source-card"><h4>${esc(src.info.auditorName||'Unnamed auditor')}</h4>${statusTag(r.status||'Unanswered')}<div class="meta-line"><b>Remark:</b> ${esc(r.auditorRemark||'—')}</div><div class="meta-line"><b>Evidence:</b> ${esc(r.evidence||'—')}</div><div class="meta-line"><b>Category / Risk:</b> ${esc(r.findingCategory||'—')} / ${esc(r.riskRating||'—')}</div>${sourcePhotosHTML(src,m,x.id,r,withActions)}${withActions?`<div class="source-actions"><button class="btn outline small" onclick="useSourceStatus('${src.id}','${m}','${x.id}')">Use status</button><button class="btn outline small" onclick="copySourceFields('${src.id}','${m}','${x.id}')">Use finding details</button></div>`:''}</div>`}
function sourcePhotosHTML(src,m,id,r,withActions){if(!r.photos?.length)return '';return `<div class="mini-photos">${r.photos.map(p=>`<div class="mini-photo"><img src="${p.dataUrl}" onclick="showRecordPhoto('${src.id}','${m}','${id}','${p.id}')"><button onclick="showRecordPhoto('${src.id}','${m}','${id}','${p.id}')">View</button>${withActions?`<button onclick="addSourcePhoto('${src.id}','${m}','${id}','${p.id}')">+ Final</button>`:''}</div>`).join('')}</div>`}
function compareItemHTML(row,src,withActions){return `<div class="compare-item ${row.disagree?'disagree':''}"><div class="qhead"><div class="num">${esc(row.x.id.replace(/^.*?-/,''))}</div><div><h3>${esc(modules[row.m].title)} • ${esc(row.x.check)}</h3><div class="sub">${esc(row.x.group+' — '+row.x.section)}${row.disagree?' • ⚠ Different auditor decision':''}</div></div></div><div class="source-grid">${src.map((s,i)=>sourceEvidenceCard(s,row.m,row.x,row.rs[i],withActions)).join('')}</div></div>`}

async function createFinalFromCompare(){const src=selectedRecords();if(src.length<2)return;const f=newState('final');f.info=clone(src[0].info);f.sopTemplate=clone(recordSopTemplate(src[0]));f.moduleTemplates=clone(src[0].moduleTemplates||snapshotModuleTemplates());f.info.auditorName='Joint Review: '+src.map(r=>r.info.auditorName||'Auditor').join(' / ');f.sourceIds=src.map(r=>r.id);f.sourceAuditMeta=src.map(r=>({id:r.id,auditorName:r.info.auditorName||'Auditor',updatedAt:r.updatedAt,score:totalStatsFor(r).score}));f.finalStatus='Draft';f.comparisonCreatedAt=now();for(const row of comparisonRows(src)){const statuses=row.rs.map(r=>r.status||'');if(statuses.every(s=>s&&s===statuses[0])){const rr=getResp(row.m,row.x.id,f);rr.status=statuses[0];rr.updatedAt=now();if(rr.status==='Complied')rr.findingCategory='No Finding'}}await dbPut(f);await refreshRecords();state=records.find(r=>r.id===f.id)||f;localStorage.setItem(CURRENT_KEY,f.id);currentView='reconcile';reconcileFilter='review';render();scrollTo({top:0,behavior:'smooth'});toast('Final review draft created')}
function finalSourceRecords(){return (state?.sourceIds||[]).map(id=>records.find(r=>r.id===id)).filter(Boolean)}
function reconcileRows(){const src=finalSourceRecords(),rows=[];Object.keys(modules).forEach(m=>allItems(m,state).forEach(x=>{const rs=src.map(s=>getResp(m,x.id,s)),statuses=rs.map(r=>r.status||'Unanswered'),unique=[...new Set(statuses)],disagree=unique.length>1,fr=getResp(m,x.id,state),needs=disagree||!fr.status||fr.status==='Not Complied';rows.push({m,x,rs,statuses,disagree,fr,needs})}));return rows}
function reconcileHTML(){if(!state||state.recordType!=='final')return `<div class="panel empty">No final review record selected.</div>`;if(isLocked(state))return homeHTML();const src=finalSourceRecords(),rdy=finalReadiness(state),rows=reconcileRows(),shown=rows.filter(r=>reconcileFilter==='all'||(reconcileFilter==='review'&&r.needs)||(reconcileFilter==='differences'&&r.disagree)||(reconcileFilter==='unresolved'&&!r.fr.status));return `<div class="module-head"><button class="back" onclick="backToTeamReview()">←</button><div><h1>Reconcile Final Result</h1><p>${esc(state.info.stateOffice)} • compare evidence, decide final status, then lock</p></div><div class="module-tools">${rdy.ready?'<button class="btn gold" onclick="finaliseRecord()">Finalise & Lock</button>':''}</div></div>${readinessHTML(rdy)}<div class="section-title"><div><h2>Source Auditors</h2><p>${src.length} source record(s) remain unchanged.</p></div></div><div class="source-grid">${src.map(sourceSummaryCard).join('')}</div><div class="sticky-tools"><div class="filter-row"><button class="chip ${reconcileFilter==='review'?'active':''}" onclick="setReconcileFilter('review')">Needs Review</button><button class="chip ${reconcileFilter==='differences'?'active':''}" onclick="setReconcileFilter('differences')">Differences</button><button class="chip ${reconcileFilter==='unresolved'?'active':''}" onclick="setReconcileFilter('unresolved')">Unresolved</button><button class="chip ${reconcileFilter==='all'?'active':''}" onclick="setReconcileFilter('all')">All Items</button></div></div>${shown.length?shown.map(r=>reconcileItemHTML(r,src)).join(''):'<div class="panel empty">No item matches this filter.</div>'}`}
function setReconcileFilter(f){reconcileFilter=f;render()}
function reconcileItemHTML(row,src){const fr=row.fr;return `<div class="compare-item ${row.disagree?'disagree':''}"><div class="qhead"><div class="num">${esc(row.x.id.replace(/^.*?-/,''))}</div><div><h3>${esc(modules[row.m].title)} • ${esc(row.x.check)}</h3><div class="sub">${esc(row.x.group+' — '+row.x.section)}${row.disagree?' • ⚠ Auditor decisions differ':''}</div></div></div><div class="reconcile-grid"><div><div class="source-grid">${src.map((s,i)=>sourceEvidenceCard(s,row.m,row.x,row.rs[i],true)).join('')}</div></div><div class="final-box"><h4>Final Decision</h4><div class="status-buttons" style="justify-content:flex-start"><button class="status complied ${fr.status==='Complied'?'selected':''}" onclick="setStatus('${row.m}','${row.x.id}','Complied')">✓ Complied</button><button class="status not ${fr.status==='Not Complied'?'selected':''}" onclick="setStatus('${row.m}','${row.x.id}','Not Complied')">✕ Not Complied</button><button class="status na ${fr.status==='N/A'?'selected':''}" onclick="setStatus('${row.m}','${row.x.id}','N/A')">N/A</button></div><div class="form-grid" style="margin-top:10px"><div class="field"><label>Finding Category</label><select onchange="updateResp('${row.m}','${row.x.id}','findingCategory',this.value)"><option value="">Select…</option>${opts(D.dropdowns.findingCategory,fr.findingCategory)}</select></div><div class="field"><label>Risk Rating</label><select onchange="updateResp('${row.m}','${row.x.id}','riskRating',this.value)"><option value="">Select…</option>${opts(D.dropdowns.riskRating,fr.riskRating)}</select></div><div class="field full"><label>Evidence Reference</label><input value="${esc(fr.evidence)}" onchange="updateResp('${row.m}','${row.x.id}','evidence',this.value)"></div><div class="field full"><label>Final Auditor Remark</label><textarea onchange="updateResp('${row.m}','${row.x.id}','auditorRemark',this.value)">${esc(fr.auditorRemark)}</textarea></div><div class="field full"><label>Final Photo Evidence</label>${photoHTML(row.m,row.x.id,fr)}</div></div></div></div></div>`}
async function useSourceStatus(srcId,m,id){const src=records.find(r=>r.id===srcId);if(!src)return;const sr=getResp(m,id,src),fr=getResp(m,id,state);fr.status=sr.status;fr.updatedAt=now();await saveState();render()}
async function copySourceFields(srcId,m,id){const src=records.find(r=>r.id===srcId);if(!src)return;const sr=getResp(m,id,src),fr=getResp(m,id,state);['findingCategory','riskRating','evidence','auditorRemark','remark'].forEach(k=>fr[k]=sr[k]||'');fr.updatedAt=now();await saveState(false);render();toast('Finding details copied')}
async function addSourcePhoto(srcId,m,id,pid){const src=records.find(r=>r.id===srcId);if(!src)return;const sp=getResp(m,id,src).photos.find(p=>p.id===pid);if(!sp)return;const fr=getResp(m,id,state);if(fr.photos.some(p=>p.sourceId===srcId&&p.sourcePhotoId===pid)){toast('Photo already in final');return}if(fr.photos.length>=6){alert('Maximum 6 final photos per checklist item.');return}fr.photos.push({...clone(sp),id:uuid(),sourceId:srcId,sourcePhotoId:pid,name:(src.info.auditorName||'Auditor')+' - '+(sp.name||'evidence.jpg')});fr.updatedAt=now();await saveState(false);render();toast('Photo added to final')}
async function finaliseRecord(){if(!state||state.recordType!=='final')return;const r=finalReadiness(state);if(!r.ready){alert('Final report is blocked until all checklist decisions and required finding details are complete.');return}if(!confirm('Finalise and lock this audit? Report outputs will use this final result.'))return;state.finalStatus='Final';state.finalisedAt=now();state.updatedAt=state.finalisedAt;await dbPut(state);await refreshRecords();state=records.find(r=>r.id===state.id)||state;currentView='review';render();toast('Final audit locked')}
async function unlockFinal(){if(!isLocked(state))return;if(!confirm('Unlock this final audit for correction? It will become Draft until finalised again.'))return;state.finalStatus='Draft';state.finalisedAt=null;state.updatedAt=now();await dbPut(state);await refreshRecords();state=records.find(r=>r.id===state.id)||state;currentView='reconcile';render()}
function openInfo(){if(!state||isReadOnly(state))return;const i=state.info,current=recordSopTemplate(state);document.getElementById('infoForm').innerHTML=`<div class="field"><label>State Office</label><select id="i_state"><option value="">Select…</option>${opts(D.stateOffices,i.stateOffice)}</select></div><div class="field"><label>Year</label><input type="number" id="i_year" value="${esc(i.year)}"></div><div class="field full"><label>Audit Document</label><input id="i_doc" value="${esc(i.auditDocument||current.name)}" placeholder="Audit document / engagement title"></div><div class="field full"><label>SOP Audit Template</label><select id="i_sop">${[current,...sopTemplates.filter(t=>t.fingerprint!==current.fingerprint)].map(t=>`<option value="${esc(t.fingerprint)}" ${t.fingerprint===current.fingerprint?'selected':''}>${esc(t.name)}${t.builtin?' (Built-in)':''}${t.fingerprint===current.fingerprint?' — current snapshot':''}</option>`).join('')}</select><div class="small" style="margin-top:5px">Only configured SOP templates appear here. Use SOP Audit → Audit Templates to add another SOP.</div></div><div class="field"><label>Audit Date</label><input type="date" id="i_date" value="${esc(i.auditDate)}"></div><div class="field"><label>Review Period</label><input id="i_period" value="${esc(i.reviewPeriod)}" placeholder="e.g. Jan–Jun 2026"></div><div class="field"><label>${state.recordType==='final'?'Reviewer / Team Name':'Auditor Name'}</label><input id="i_auditor" value="${esc(i.auditorName)}"></div><div class="field"><label>Auditee Name</label><input id="i_auditee" value="${esc(i.auditeeName)}"></div>`;document.getElementById('infoModal').classList.add('open')}
function closeInfo(){document.getElementById('infoModal').classList.remove('open')}
async function saveInfo(){if(isReadOnly(state))return;const oldSop=recordSopTemplate(state),newSop=templateByFingerprint(document.getElementById('i_sop').value,state),hasSopData=Object.entries(state.responses||{}).some(([k,v])=>k.startsWith('sop::')&&v&&(v.status||v.auditorRemark||v.evidence||(v.photos||[]).length));if(oldSop.fingerprint!==newSop.fingerprint&&hasSopData&&!confirm('Change the SOP template for this audit? Existing SOP responses will remain stored but will no longer appear in the active checklist.'))return;state.sopTemplate=clone(newSop);state.info={stateOffice:document.getElementById('i_state').value,year:document.getElementById('i_year').value,auditDocument:document.getElementById('i_doc').value||newSop.name,auditDate:document.getElementById('i_date').value,reviewPeriod:document.getElementById('i_period').value,auditorName:document.getElementById('i_auditor').value,auditeeName:document.getElementById('i_auditee').value};state.infoUpdatedAt=now();await saveState(false);closeInfo();render()}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1700)}
function download(name,blob){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000)}
function safeName(r=state){return ((r?.info?.stateOffice)||'Audit').replace(/[^a-z0-9]+/gi,'_')+'_'+((r?.info?.auditDate)||'')}
function exportBackup(){download('Audit_QMOD_Backup_'+safeName()+'.json',new Blob([JSON.stringify({app:'Audit QMOD',version:3,type:'record',record:state},null,2)],{type:'application/json'}))}
function exportRecordBackup(id){const r=records.find(x=>x.id===id);if(r)download('Audit_QMOD_Backup_'+safeName(r)+'.json',new Blob([JSON.stringify({app:'Audit QMOD',version:3,type:'record',record:r},null,2)],{type:'application/json'}))}
function exportAuditorSubmission(id){const r=records.find(x=>x.id===id);if(!r||r.recordType==='final')return;if(!r.info.stateOffice||!r.info.auditorName){alert('Set State Office and Auditor Name first.');return}const pkg=makeSubmissionPackage(r),name=submissionFilename(r,pkg.manifest.submissionId);download(name,new Blob([JSON.stringify(pkg)],{type:'application/json'}));toast('.qmod audit result saved')}
async function exportAllBackup(){const all=await dbAll(),templates=(await dbTemplateAll());download('Audit_QMOD_All_Records.json',new Blob([JSON.stringify({app:'Audit QMOD',version:5.7,type:'bundle',records:all,sopTemplates:templates},null,2)],{type:'application/json'}))}
async function importOneRecord(r,{asSubmission=false,manifest=null,fileName=''}={}){r=clone(r);if(asSubmission&&manifest?.submissionId){const dup=records.find(x=>x.importManifest?.submissionId===manifest.submissionId);if(dup)return {duplicate:true,record:dup}}const existing=records.find(x=>x.id===r.id);if(existing||asSubmission){r.sourceRecordId=r.id;r.id=uuid()}r.recordType=r.recordType||'auditor';r.importedAt=now();if(manifest)r.importManifest={...manifest,fileName};r.deletedAt=null;r.updatedAt=r.updatedAt||now();for(const v of Object.values(r.responses||{})){v.photos=v.photos||[];v.updatedAt=v.updatedAt||r.updatedAt}await dbPut(r);return {duplicate:false,record:r}}
function importBackup(ev){const f=ev.target.files[0];if(!f)return;const rd=new FileReader();rd.onload=async()=>{try{const x=JSON.parse(rd.result);if(x.type==='bundle'){for(const r of x.records||[])await importOneRecord(r);for(const t of x.sopTemplates||[])await dbTemplatePut(normalizeSopTemplate(t));await refreshSopTemplates()}else if(x.type==='record')await importOneRecord(x.record);else if(x.type==='auditor_submission')await importOneRecord(x.record,{asSubmission:true,manifest:x.manifest});else if(x.info&&x.responses)await importOneRecord(x);else throw 0;await refreshRecords();state=null;currentView='records';render();toast('Backup imported')}catch(e){alert('Invalid Audit QMOD backup file.')}};rd.readAsText(f);ev.target.value=''}
async function importAuditorSubmissions(ev){const files=[...ev.target.files];if(!files.length)return;let ok=0,bad=0,dup=0;for(const f of files){try{const txt=await f.text(),x=JSON.parse(txt);if(x.type!=='auditor_submission'||!x.record)throw 0;const out=await importOneRecord(x.record,{asSubmission:true,manifest:x.manifest,fileName:f.name});out?.duplicate?dup++:ok++}catch(e){bad++}}await refreshRecords();currentView='team';state=null;render();toast(ok+' team result(s) imported'+(dup?' • '+dup+' duplicate skipped':'')+(bad?' • '+bad+' invalid':''));ev.target.value=''}
function reportRows(){const rows=[];Object.keys(modules).forEach(m=>allItems(m,state).forEach(x=>{const r=getResp(m,x.id);rows.push({module:modules[m].title,group:x.group,section:x.section,id:x.id,sampleId:x.sampleId||'',check:x.check,evidenceExpected:x.evidenceExpected,status:r.status||'Unanswered',findingCategory:r.findingCategory||'',riskRating:r.riskRating||'',evidence:r.evidence||'',auditorRemark:r.auditorRemark||'',remark:r.remark||'',photos:r.photos||[]})}));return rows}
function xml(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function assertFinalForReport(){if(!state||state.recordType!=='final'||state.finalStatus!=='Final'){alert('Final report can only be generated after reconciliation and Finalise & Lock.');return false}return true}
function exportExcel(){if(!assertFinalForReport())return;const rows=reportRows(),t=totalStats(),sheets=[],summary=[['FINAL AUDIT SUMMARY',''],['State Office',state.info.stateOffice],['Audit Document',state.info.auditDocument],['SOP Audit Template',recordSopTemplate(state).name+(recordSopTemplate(state).version?' v'+recordSopTemplate(state).version:'')],['Year',state.info.year],['Audit Date',state.info.auditDate],['Reviewer(s)',state.info.auditorName],['Auditee Name',state.info.auditeeName],['Review Period',state.info.reviewPeriod],['Finalised At',state.finalisedAt],['Source Auditors',(finalSourceRecords().length?finalSourceRecords().map(r=>r.info.auditorName):(state.sourceAuditMeta||[]).map(x=>x.auditorName)).join('; ')],['',''],['Complied',t.c],['Not Complied',t.n],['N/A',t.na],['Unanswered',t.p],['Compliance Score',t.score+'%'],['Conclusion',auditConclusion(state)],['','']];for(const [m,def] of Object.entries(modules)){summary.push([def.title+' Compliance by Section','']);for(const ss of sectionStatsFor(state,m))summary.push([ss.section,ss.score+'%']);summary.push(['',''])}summary.push(['Key Finding Summary','']);keyFindingSummary(state).forEach(x=>summary.push(['Finding',x]));sheets.push(['Summary',summary]);for(const [m,def] of Object.entries(modules)){const rr=rows.filter(r=>r.module===def.title);sheets.push([def.title,[['ID','Sample ID','Group','Section','Audit Check','Evidence Expected','Final Status','Finding Category','Risk Rating','Evidence Link / Reference','Photo Count','Photo Names','Final Auditor Remark','Remark'],...rr.map(r=>[r.id,r.sampleId,r.group,r.section,r.check,r.evidenceExpected,r.status,r.findingCategory,r.riskRating,r.evidence,r.photos.length,r.photos.map(p=>p.name).join('; '),r.auditorRemark,r.remark])]])}let out=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Styles><Style ss:ID="Header"><Font ss:Bold="1"/><Interior ss:Color="#D9EAF7" ss:Pattern="Solid"/></Style></Styles>`;for(const [name,table] of sheets){out+=`<Worksheet ss:Name="${xml(name.slice(0,31))}"><Table>`;table.forEach((row,ri)=>{out+='<Row>';row.forEach(v=>{const n=typeof v==='number';out+=`<Cell${ri===0?' ss:StyleID="Header"':''}><Data ss:Type="${n?'Number':'String'}">${xml(v)}</Data></Cell>`});out+='</Row>'});out+='</Table></Worksheet>'}out+='</Workbook>';download('Audit_QMOD_FINAL_'+safeName()+'.xls',new Blob([out],{type:'application/vnd.ms-excel'}));toast('Final Excel report generated')}
function photoReport(rows){const withP=rows.filter(r=>r.photos?.length);if(!withP.length)return '<p>No photo evidence attached.</p>';return withP.map(r=>`<div class="ev"><h3>${esc(r.module)} • ${esc(r.id)}</h3><div class="q">${esc(r.check)}</div><div class="evpics">${r.photos.map(p=>`<figure><img src="${p.dataUrl}"><figcaption>${esc(p.name)}</figcaption></figure>`).join('')}</div></div>`).join('')}
function reportHTML(){const t=totalStats(),rows=reportRows(),findings=rows.filter(r=>r.status==='Not Complied'),sources=finalSourceRecords(),sourceNames=sources.length?sources.map(r=>r.info.auditorName||'Auditor'):(state.sourceAuditMeta||[]).map(x=>x.auditorName||'Auditor');return `<!doctype html><html><head><meta charset="utf-8"><title>Audit QMOD Final Report</title><style>body{font-family:Arial,sans-serif;color:#172033;font-size:10pt;margin:28px}h1{color:#123b63;margin-bottom:3px}h2{color:#123b63;margin-top:24px;border-bottom:2px solid #d8a928;padding-bottom:5px}h3{color:#123b63;margin-bottom:4px}.meta{border-collapse:collapse;width:100%;margin:14px 0}.meta td{border:1px solid #d9dee5;padding:7px}.meta td:first-child{font-weight:bold;width:24%;background:#f5f7fb}table.data{border-collapse:collapse;width:100%;font-size:8pt}table.data th,table.data td{border:1px solid #cfd7df;padding:5px;vertical-align:top}table.data th{background:#123b63;color:white}.bad{color:#b42318;font-weight:bold}.good{color:#087a55;font-weight:bold}.kpis{display:flex;gap:10px;margin:12px 0}.k{border:1px solid #d9dee5;padding:10px;min-width:110px}.k b{font-size:16pt;display:block}.overall-result{margin:18px 0 22px}.overall-title{background:#8fb583;color:#fff;font-weight:bold;font-size:14pt;padding:9px 14px;border-radius:22px}.overall-title span{display:inline-flex;width:25px;height:25px;border-radius:50%;background:#fff;color:#6d9364;align-items:center;justify-content:center;margin-right:7px}.result-modules{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:16px}.result-module{border:1px solid #999;padding:9px}.result-module h3{text-align:center;color:#555;font-size:9pt;margin:0 0 10px}.result-row{display:grid;grid-template-columns:42% 1fr;gap:4px;align-items:center;margin:7px 0}.result-label{font-size:6.5pt;color:#666}.result-track{height:19px;background:#f2f2f2;position:relative}.result-bar{height:100%;background:#df2a91}.result-track span{position:absolute;right:3px;top:4px;font-size:6pt}.result-summary{margin-top:14px;font-size:9pt}.result-summary ul{margin:4px 0 10px 18px;padding:0}.result-summary p{margin:3px 0 10px}@media(max-width:800px){.result-modules{grid-template-columns:1fr 1fr}}.page{page-break-before:always}.ev{page-break-inside:avoid;border-bottom:1px solid #ddd;padding-bottom:12px;margin-bottom:14px}.q{font-size:9pt;margin-bottom:8px}.evpics{display:flex;gap:8px;flex-wrap:wrap}.evpics figure{margin:0;width:31%}.evpics img{width:100%;max-height:220px;object-fit:contain;border:1px solid #ddd}.evpics figcaption{font-size:7pt;color:#667085;margin-top:3px}@media print{body{margin:12mm}}</style></head><body><h1>QMOD Final Audit Report</h1><div>Reconciled result generated by Audit QMOD</div><table class="meta"><tr><td>State Office</td><td>${esc(state.info.stateOffice)}</td></tr><tr><td>Audit Document</td><td>${esc(state.info.auditDocument)}</td></tr><tr><td>SOP Audit Template</td><td>${esc(recordSopTemplate(state).name)}${recordSopTemplate(state).version?' v'+esc(recordSopTemplate(state).version):''}</td></tr><tr><td>Year / Date</td><td>${esc(state.info.year)} / ${esc(state.info.auditDate)}</td></tr><tr><td>Reviewer(s)</td><td>${esc(state.info.auditorName)}</td></tr><tr><td>Source Auditors</td><td>${esc(sourceNames.join(', '))}</td></tr><tr><td>Auditee</td><td>${esc(state.info.auditeeName)}</td></tr><tr><td>Review Period</td><td>${esc(state.info.reviewPeriod)}</td></tr><tr><td>Finalised</td><td>${esc(fmtDate(state.finalisedAt))}</td></tr></table><div class="kpis"><div class="k"><b>${t.c}</b>Complied</div><div class="k"><b>${t.n}</b>Not Complied</div><div class="k"><b>${t.p}</b>Unanswered</div><div class="k"><b>${t.score}%</b>Compliance</div></div>${auditResultDashboardHTML(state,true)}<h2>Non-Compliance Findings</h2>${findings.length?tableHTML(findings):'<p>No non-compliance findings recorded.</p>'}<h2 class="page">Photo Evidence</h2>${photoReport(rows)}<h2 class="page">Complete Checklist</h2>${tableHTML(rows)}</body></html>`}
function tableHTML(rows){return `<table class="data"><thead><tr><th>Module</th><th>Section</th><th>Audit Check</th><th>Final Status</th><th>Category / Risk</th><th>Evidence</th><th>Photos</th><th>Final Auditor Remark</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.module)}</td><td>${esc(r.group+' / '+r.section)}</td><td>${esc(r.check)}<br><small>Expected: ${esc(r.evidenceExpected)}</small></td><td class="${r.status==='Not Complied'?'bad':r.status==='Complied'?'good':''}">${esc(r.status)}</td><td>${esc(r.findingCategory)}${r.riskRating?'<br>'+esc(r.riskRating):''}</td><td>${esc(r.evidence)}</td><td>${r.photos.length}</td><td>${esc(r.auditorRemark)}${r.remark?'<br><i>'+esc(r.remark)+'</i>':''}</td></tr>`).join('')}</tbody></table>`}
function exportWord(){if(!assertFinalForReport())return;download('Audit_QMOD_FINAL_'+safeName()+'.doc',new Blob(['\ufeff',reportHTML()],{type:'application/msword'}));toast('Final Word report generated')}
function printReport(){if(!assertFinalForReport())return;const w=window.open('','_blank');if(!w){alert('Please allow pop-ups to generate the PDF/print report.');return}w.document.open();w.document.write(reportHTML());w.document.close();setTimeout(()=>{w.focus();w.print()},350)}


function makeSubmissionPackage(r){return {app:'Audit QMOD',version:5.7,type:'auditor_submission',manifest:{submissionId:uuid(),preparedAt:now(),recipient:EMAIL_RECIPIENT,recordId:r.id,stateOffice:r.info.stateOffice,year:r.info.year,auditDocument:r.info.auditDocument,auditDate:r.info.auditDate,auditorName:r.info.auditorName,updatedAt:r.updatedAt},record:clone(r)}}
function submissionFilename(r,submissionId=''){const stamp=new Date().toISOString().replace(/[-:TZ.]/g,'').slice(0,14);return `AQMOD_${safeFile(r.info.stateOffice||'State')}_${safeFile(r.info.year||'Year')}_${safeFile(r.info.auditDate||'Date')}_${safeFile(r.info.auditorName||'Auditor')}_${stamp}${submissionId?'_'+submissionId.slice(0,8):''}.qmod`}
async function emailAuditResult(id){const r=records.find(x=>x.id===id);if(!r||r.recordType==='final'||r.importedAt)return;if(!r.info.stateOffice||!r.info.auditorName||!r.info.auditDate){alert('Set State Office, Audit Date and Auditor Name before emailing the result.');return}const pkg=makeSubmissionPackage(r),name=submissionFilename(r,pkg.manifest.submissionId),json=JSON.stringify(pkg),file=new File([json],name,{type:'application/json'}),subject=`Audit QMOD | ${r.info.stateOffice} | ${r.info.year} | ${r.info.auditorName}`,body=`Audit QMOD auditor result attached.\n\nState Office: ${r.info.stateOffice}\nAudit Date: ${r.info.auditDate}\nAuditor: ${r.info.auditorName}\n\nPlease retain the .qmod attachment for Team Review.`;try{if(navigator.share&&navigator.canShare&&navigator.canShare({files:[file]})){await navigator.share({title:subject,text:body,files:[file]});r.lastEmailPreparedAt=now();r.lastEmailRecipient=EMAIL_RECIPIENT;await dbPut(r);await refreshRecords();render();toast('Audit result ready to send');return}}catch(e){if(e&&e.name==='AbortError')return}download(name,new Blob([json],{type:'application/json'}));r.lastEmailPreparedAt=now();r.lastEmailRecipient=EMAIL_RECIPIENT;await dbPut(r);await refreshRecords();render();const mail=`mailto:${encodeURIComponent(EMAIL_RECIPIENT)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body+'\n\nThe .qmod file has been downloaded. Please attach it to this email before sending.')}`;alert(`Audit result ${name} has been downloaded. The email composer will open next. Attach the downloaded .qmod file, then Send.`);location.href=mail}
function safeFile(v){return String(v??'').trim().replace(/[^a-z0-9._-]+/gi,'_').replace(/^_+|_+$/g,'').slice(0,60)||'Audit'}
async function loadTeamReview(){state=null;currentView='team';render();scrollTo({top:0,behavior:'smooth'})}
function auditIdentityKey(r){return [r.info.stateOffice||'',String(r.info.year||''),r.info.auditDocument||'',r.info.auditDate||'',templateFingerprintKey(r)].join('||')}
function teamGroups(){const map=new Map();for(const r of records.filter(x=>x.recordType!=='final')){const k=auditIdentityKey(r);if(!map.has(k))map.set(k,{key:k,records:[]});map.get(k).records.push(r)}return [...map.values()].map(g=>{g.records.sort((a,b)=>ts(b.updatedAt)-ts(a.updatedAt));g.latest=Math.max(...g.records.map(r=>ts(r.updatedAt)));return g}).sort((a,b)=>b.latest-a.latest)}
function finalReviewCard(r){const t=totalStatsFor(r),locked=r.finalStatus==='Final';return `<div class="panel record final"><div class="score">${t.score}%</div><div><span class="badge final">${locked?'Final Report':'Final Review Draft'}</span>${locked?'<span class="badge locked">LOCKED</span>':''}</div><div class="eyebrow" style="margin-top:8px">${esc(r.info.year||'—')}</div><h3>${esc(r.info.stateOffice||'Unnamed Audit')}</h3><p>${esc(r.info.auditDate||'No audit date')} • ${(r.sourceIds||[]).length} source auditor(s) • ${t.n} finding(s)</p><div class="stamp">Updated ${esc(fmtDate(r.updatedAt))}</div><div class="record-actions"><button class="btn primary small" onclick="openAuditRecord('${r.id}')">${locked?'Open Report':'Continue Review'}</button><button class="btn danger small" onclick="deleteFinalReviewRecord('${r.id}')">Delete</button></div></div>`}
function teamHTML(){const groups=teamGroups(),imported=records.filter(r=>r.recordType!=='final'&&r.importedAt).length,finals=records.filter(r=>r.recordType==='final'),hasDemo=records.some(isDemoRecord);return `<div class="module-head"><button class="back" onclick="backToDashboard()">←</button><div><div class="page-kicker">Reviewer Workspace</div><h1>Review Audit</h1><p>Import auditor result files, compare differences, review evidence and reconcile the final decision.</p></div><div class="module-tools"><button class="btn gold" onclick="document.getElementById('submissionFile').click()">Import Team Results</button><button class="btn outline" onclick="seedDemoTeamLocal()">Demo Team Data</button>${hasDemo?'<button class="btn danger" onclick="purgeDemoData()">Delete Demo Data</button>':''}</div></div><div class="callout">Auditor results remain separate and read-only. Import all .qmod result files for the same audit session, then compare them before creating a Final Review record.</div><section class="summary-grid"><div class="panel kpi"><div class="n">${groups.length}</div><div class="l">Audit Sessions</div></div><div class="panel kpi"><div class="n">${imported}</div><div class="l">Imported Results</div></div><div class="panel kpi"><div class="n">${records.filter(r=>r.recordType==='final'&&r.finalStatus==='Draft').length}</div><div class="l">Final Review Drafts</div></div><div class="panel kpi good"><div class="n">${records.filter(r=>r.recordType==='final'&&r.finalStatus==='Final').length}</div><div class="l">Finalised</div></div></section>${groups.length?groups.map(teamGroupHTML).join(''):'<div class="panel empty">No auditor results yet. Select <b>Import Team Results</b> and choose all .qmod files for the same audit session.</div>'}${finals.length?`<div class="section-title"><div><h2>Final Review Records</h2><p>Continue a draft, open a final report, or delete test/review records that are no longer needed.</p></div></div><section class="record-grid">${finals.map(finalReviewCard).join('')}</section>`:''}${compareSelection.size?`<div class="panel compare-bar"><div><b>${compareSelection.size} auditor result(s) selected</b><div class="smalltxt">Select 2–3 results from the same audit session.</div></div><div><button class="btn outline small" onclick="clearCompareSelection()">Clear</button> <button class="btn gold" onclick="startCompare()" ${compareSelection.size<2?'disabled':''}>Compare Selected</button></div></div>`:''}`}
function teamGroupHTML(g){const rs=g.records,b=rs[0],eligible=rs.length>=2&&rs.length<=3;let diff='—',agree='—';if(eligible){const rows=comparisonRows(rs);diff=rows.filter(x=>x.disagree).length;agree=rows.filter(x=>!x.disagree&&!x.allBlank).length}return `<div class="section-title"><div><h2>${esc(b.info.stateOffice||'Unnamed')} • ${esc(b.info.year||'')}</h2><p>${esc(b.info.auditDocument||'')} • SOP: ${esc(recordSopTemplate(b).name)}${recordSopTemplate(b).version?' v'+esc(recordSopTemplate(b).version):''} • Audit Date ${esc(b.info.auditDate||'—')} • ${rs.length} auditor result(s)</p></div>${eligible?`<button class="btn primary" onclick="reviewAuditGroup('${encodeURIComponent(g.key)}')">Review ${rs.length} Auditors</button>`:''}</div><div class="panel" style="padding:14px"><div class="overview-grid" style="margin-bottom:12px"><div class="overview-card"><h4>Auditors</h4><div class="big">${rs.length}</div></div><div class="overview-card"><h4>Agreed</h4><div class="big">${agree}</div></div><div class="overview-card"><h4>Different</h4><div class="big">${diff}</div></div><div class="overview-card"><h4>Status</h4><div class="big" style="font-size:15px">${rs.length<2?'Waiting':rs.length>3?'Select 3':diff===0?'Aligned':'Review'}</div></div></div><div class="source-grid">${rs.map(r=>`<div class="source-card"><div>${r.importedAt?'<span class="badge imported">IMPORTED</span>':'<span class="badge">LOCAL</span>'}</div><h4 style="margin-top:7px">${esc(r.info.auditorName||'Auditor')}</h4><div class="meta-line">${totalStatsFor(r).score}% compliance • ${totalStatsFor(r).n} finding(s)<br>${r.importManifest?.fileName?esc(r.importManifest.fileName):'Local working record'}</div><label class="record-select"><input type="checkbox" ${compareSelection.has(r.id)?'checked':''} onchange="toggleCompareSelection('${r.id}',this.checked)"> Select</label><div class="source-actions"><button class="btn outline small" onclick="openAuditRecord('${r.id}')">View</button><button class="btn danger small" onclick="deleteReviewSource('${r.id}')">Delete</button></div></div>`).join('')}</div></div>`}
function reviewAuditGroup(encodedKey){const key=decodeURIComponent(encodedKey),g=teamGroups().find(x=>x.key===key);if(!g)return;if(g.records.length<2){alert('At least 2 auditor results are required.');return}if(g.records.length>3){alert('This audit has more than 3 results. Select the 3 records you want to compare manually.');return}compareSelection.clear();g.records.forEach(r=>compareSelection.add(r.id));startCompare()}
async function seedDemoTeamLocal(){if(records.some(isDemoRecord)){if(!confirm('Demo data already exists. Replace the existing demo data?'))return;await purgeDemoData(false)}const names=['Auditor A','Auditor B','Auditor C'];for(let i=0;i<3;i++){const r=newState('auditor');r.info={...r.info,stateOffice:'SBSO',year:2026,auditDocument:D.mainDefaults.auditDocument||'SOP Compliance Audit',auditDate:'2026-09-08',auditorName:names[i],auditeeName:'KK Branch Office',reviewPeriod:'2026'};for(const m of Object.keys(modules)){for(const x of allItems(m,r)){const rr=getResp(m,x.id,r);rr.status='Complied';rr.findingCategory='No Finding';rr.updatedAt=now()}}const diffs=[['pcs',allItems('pcs',r)[3]],['wireless',allItems('wireless',r)[5]],['sop',allItems('sop',r)[8]]];if(i===0){let rr=getResp(diffs[0][0],diffs[0][1].id,r);rr.status='Not Complied';rr.findingCategory='Documentation Gap';rr.riskRating='Medium';rr.auditorRemark='Supporting evidence was not available during the audit.'}if(i===1){let rr=getResp(diffs[1][0],diffs[1][1].id,r);rr.status='Not Complied';rr.findingCategory='Process Gap';rr.riskRating='High';rr.auditorRemark='Observed process differs from the documented workflow.'}if(i===2){let rr=getResp(diffs[2][0],diffs[2][1].id,r);rr.status='N/A';rr.auditorRemark='Auditor considered this item not applicable for the reviewed period.'}r.demoData=true;const manifest={submissionId:uuid(),preparedAt:now(),recipient:EMAIL_RECIPIENT,stateOffice:r.info.stateOffice,year:r.info.year,auditDocument:r.info.auditDocument,auditDate:r.info.auditDate,auditorName:r.info.auditorName,demo:true};await importOneRecord(r,{asSubmission:true,manifest,fileName:`DEMO_${names[i].replace(/ /g,'_')}.qmod`})}await refreshRecords();compareSelection.clear();currentView='team';render();toast('3 demo auditor results created')}
function showRecordPhoto(recordId,m,id,pid){const rec=records.find(r=>r.id===recordId)||(state&&state.id===recordId?state:null);if(!rec)return;const p=getResp(m,id,rec).photos.find(x=>x.id===pid);if(!p)return;document.getElementById('lightboxImg').src=p.dataUrl;document.getElementById('lightboxCaption').textContent=(rec.info.auditorName||'Evidence')+' • '+(p.name||'photo');document.getElementById('lightbox').classList.add('open')}
function closeLightbox(e,force=false){if(force||e.target.id==='lightbox')document.getElementById('lightbox').classList.remove('open')}

async function migrateV1(){try{const old=JSON.parse(localStorage.getItem('auditku_v1_state')||'null');if(old?.info&&old?.responses){const existing=await dbAll();if(!existing.length){const t=old.updatedAt||now(),r={...old,id:uuid(),recordType:'auditor',infoUpdatedAt:t,deletedAt:null};for(const v of Object.values(r.responses||{})){v.photos=v.photos||[];v.updatedAt=v.updatedAt||t}await dbPut(r)}localStorage.removeItem('auditku_v1_state')}}catch(e){}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e});
async function installPWA(){if(!deferredInstall)return;deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null}
async function init(){db=await openDB();await migrateV1();await migrateModuleTemplateSnapshots();loadCachedRepoPack();await refreshSopTemplates();await refreshRecords();state=null;currentView='dashboard';currentModule=null;render();syncRepoTemplates().then(async ok=>{if(ok){await refreshRecords();render()}})}


// Audit QMOD v5.7 startup — render the landing dashboard after the DOM is ready.
document.addEventListener('DOMContentLoaded', () => {
  init().catch(err => {
    console.error('Audit QMOD failed to start', err);
    const app = document.getElementById('app');
    if (app) app.innerHTML = `<div class="panel" style="max-width:760px;margin:40px auto;padding:22px"><h2>Audit QMOD could not start</h2><p>Please refresh the page. If this remains, clear this site's cached data once and reopen.</p><pre style="white-space:pre-wrap;font-size:12px">${String(err?.message || err)}</pre></div>`;
  });
});
